/* Convertit un manuscrit texte en lecture en ligne. Les titres et questions
   restent ainsi cohérents pour chaque nouvel article importé. */
window.formaterArticleTexte = function(texte) {
  const estTempsDesNations = texte.includes('I. INTRODUCTION : COMPRENDRE LE CADRE PROPHETIQUE ET CHRONOLOGIQUE');
  const echapper = function(valeur) {
    return valeur.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  };
  const ajouterNoteBym = function(valeur) {
    if(estTempsDesNations) return valeur.replace(/\s*—\s*BYM1\b/g, ' — BYM');
    return valeur.replace(/\s*—\s*BYM1\b/g, ' — BYM<sup class="note-marque" tabindex="0" data-note="BYM : Bible de Yéhoshoua ha-Mashiyah, version citée dans cet article.">1</sup>');
  };
  const ajouterNotesManuscrit = function(valeur) {
    return valeur.replace(/\[\[FN:(\d+)\]\]/g, function(marque, id) {
      const note = NOTES_MANUSCRIT_BAPTEMES[id];
      return note ? '<sup class="note-marque" tabindex="0" data-note="' + echapper(note) + '">' + id + '</sup>' : '';
    });
  };
  const ajouterNotesTempsDesNations = function(valeur) {
    if(!estTempsDesNations) return valeur;
    const ajouter = function(texte, repere, numero) {
      const marque = '<sup class="note-marque" tabindex="0" data-note="' + echapper(texte) + '">' + numero + '</sup>';
      return valeur.includes(repere) ? valeur.replace(repere, repere + marque) : valeur;
    };

    valeur = ajouter('Verset biblique tiré de la version la Bible de Yéhoshoua.', 'Hébreux 1 : 1-2', 1);
    valeur = ajouter('Nom généralement traduit par Paul. Il s’agit de la prononciation de son nom latin (Paulus), l’apôtre étant citoyen romain de naissance (Actes 22 : 28) et écrivant dans le contexte de l’Empire romain. Le texte grec du Nouveau Testament utilise la translittération Paulos (Παῦλος).', 'Paulus', 2);
    valeur = ajouter('Cette approche est une lecture spirituelle et non une chronologie littérale. Elle ne doit donc pas être prise au sens mathématiques ou temporel absolu. Nous n’avons nullement la prétention de fixer une date, mais de proposer une clé de compréhension spirituelle pour discerner les temps dans lesquels nous vivons.', 'début de la 4ème', 3);
    valeur = ajouter('Nom généralement traduit par Jérusalem.', 'capitale Yeroushalaïm', 4);
    valeur = ajouter('Nom généralement traduit par Assyrie.', '’Ashshuwr', 5);
    valeur = ajouter('Le fait qu’Èlohiym s’est tourné vers les nations ne veut pas dire que l’Église a remplacé Yisra’él. Bien au contraire, ils sont toujours dans le plan d’Èlohiym (Romains 11 : 1-36).', 'au travers de l’Église', 6);
    valeur = ajouter('Nom généralement traduit par Daniel.', 'Ce fut le prophète Daniy’él', 7);
    valeur = ajouter('Nom généralement traduit par Timothée.', 'Timotheos', 8);
    valeur = ajouter('La grande mer correspond à la mer méditerranée.', 'grande mer', 9);
    valeur = ajouter('Texte extrait du site : https://wol.jw.org/fr/wol/d/r30/lp-f/1988208', 'les étrangers parlaient des Mèdes et des Perses [...]', 10);
    valeur = ajouter('La majorité des spécialistes identifient Yavan avec les Ioniens, un des grands groupes grecs de l’Antiquité. Dans le contexte biblique, il renvoie au roi Alexandre le Grand.', 'roi de Yavan', 11);
    valeur = ajouter('Voici le lien pour accéder au site : https://test.afriksoir.net/cote-divoire-jesus-baoule-vien-detre-libere/?_gl=1*mmb78a*_ga*MTEyODQ1MDI4NS4xNzgzMDEwNzg5*_ga_', 'Jésus d’une église', 12);
    valeur = ajouter('Voici le lien de l’extrait de texte: https://www.leparisien.fr/faits-divers/gourou-dune-secte-le-jesus-de-siberie-condamne-a-12-ans-pour-extorsion-et-pression-psychologique-04-07-2025-YW5FDMMBHVDL3FBTDXC6N2BQ34.php?ts=1783011605953', 'réincarnation du Christ', 13);
    return ajouter('Site qui nous renseigne sur la persécution des chrétiens dans le monde : https://www.portesouvertes.fr', 'Portes Ouvertes', 14);
  };
  const lignes = texte.replace(/\r\n?/g, '\n').split('\n');
  const html = [];
  let sousTitreAttendu = false;
  let listeOuverte = false;
  const fermerListe = function() {
    if(listeOuverte) { html.push('</ul>'); listeOuverte = false; }
  };

  lignes.forEach(function(brut) {
    const ligne = brut.trim();
    if(!ligne) { fermerListe(); return; }
    const contenu = ajouterNotesManuscrit(ajouterNotesTempsDesNations(ajouterNoteBym(echapper(ligne))));

    if(/^##\s+/.test(ligne)) {
      fermerListe();
      html.push('<h3>' + contenu.replace(/^##\s+/, '') + '</h3>');
      sousTitreAttendu = false;
      return;
    }
    if(/^###\s+/.test(ligne)) {
      fermerListe();
      html.push('<h4>' + contenu.replace(/^###\s+/, '') + '</h4>');
      sousTitreAttendu = false;
      return;
    }
    if(/^[IVXLC]+\.\s+/.test(ligne)) {
      fermerListe();
      html.push('<h3>' + contenu + '</h3>');
      sousTitreAttendu = true;
      return;
    }
    if(/^\d+\.\s+.*\?$/.test(ligne)) {
      fermerListe();
      html.push('<h4>' + contenu + '</h4>');
      sousTitreAttendu = false;
      return;
    }
    if(sousTitreAttendu) {
      fermerListe();
      html.push('<h4>' + contenu + '</h4>');
      sousTitreAttendu = false;
      return;
    }
    if(/^[•→]\s*/.test(ligne)) {
      if(!listeOuverte) { html.push('<ul>'); listeOuverte = true; }
      html.push('<li>' + contenu.replace(/^[•→]\s*/, '') + '</li>');
      return;
    }
    fermerListe();
    const citation = ligne.match(/^«\s*(.*?)\s*»\s*(?:\.?\s*\((.+)\))?\s*[.;]?$/);
    if(citation) {
      const texteCitation = ajouterNotesManuscrit(ajouterNotesTempsDesNations(echapper(citation[1])));
      const reference = citation[2] ? '<cite>' + ajouterNotesManuscrit(ajouterNotesTempsDesNations(ajouterNoteBym(echapper(citation[2])))) + '</cite>' : '';
      html.push('<blockquote><p>« ' + texteCitation + ' »</p>' + reference + '</blockquote>');
      return;
    }
    html.push('<p>' + contenu + '</p>');
  });
  fermerListe();
  return html.join('\n');
};


window.ARTICLES_CONTENU["Les temps des Nations"] = window.formaterArticleTexte("I. INTRODUCTION : COMPRENDRE LE CADRE PROPHETIQUE ET CHRONOLOGIQUE\r\nAvant-propos et contexte mondial\r\n“La fin des temps”, “les derniers jours”, “l'achèvement de l'âge” : autant de termes bibliques utilisés dans la Bible et dans le milieu évangélique pour désigner la période précédant le retour du Seigneur. Cette époque est jalonnée de nombreux marqueurs qui ne cessent de progresser, tels que les guerres, les famines, les violences, la rébellion des nations et les persécutions. Ce sont là des signes manifestes qui nous montrent que nous sommes proches de la fin.\r\nEn effet, le conflit au Moyen-Orient qui tend à devenir un conflit régional avec une perspective mondiale au vu des nations qui s'y préparent agit comme un véritable magma en ébullition. Elle constitue la parfaite illustration des prophéties du Seigneur Yehowshuw‘a ha-Mashiyah (Jésus-Christ). Face à cette situation mondiale, les hommes de tous horizons (scientifiques, politologues, religieux ou athées) se penchent sur une question cruciale : est-ce bientôt la fin du monde ? C’est précisément ici que la Bible, là où les hommes spéculent souvent sans parvenir à la vérité, apporte des précisions des plus étonnantes sur le déroulement des événements.\r\nLe Seigneur Yehowshuw‘a ha-Mashiyah a déclaré :\r\n« Mais vous êtes sur le point d'entendre des guerres et des bruits de guerres : Faites attention ! Ne soyez pas troublés, car il faut que toutes ces choses arrivent, mais ce n'est pas encore la fin. Car nation se réveillera contre nation et royaume contre royaume, et il y aura des famines, des pestes et des tremblements de terre en divers lieux. Mais toutes ces choses ne seront que le commencement des douleurs. » (Matthieu 24 : 6-8).\r\nCes propos, annoncés il y a plus de deux mille ans, ont autant de valeur aujourd'hui qu'à l'instant où ils ont été prononcés. Ils méritent donc que nous nous y penchions avec le plus grand sérieux. Dès lors, le choix du titre de notre article n'est pas le fruit du hasard ou d'un égarement d'esprit, mais le résultat des réponses aux multiples questions que nous nous posons sur la situation actuelle des nations et son issue.\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n1. Qu’est-ce que la fin des temps ?\r\nMentionnée 48 reprises dans les textes de la Nouvelle Alliance, la fin des temps est la période qui précède le retour glorieux de notre Seigneur Yehowshuw‘a ha-Mashiyah pour son règne millénaire sur la terre (Apocalypse 20 : 4-6).\r\nCe concept est tiré de l'adjectif grec εσχατος (eschatos) dont l’un des sens est : “dernier dans une succession dans le temps”. Ainsi, à titre d'illustration, si l'on prend un ruban que l'on divise en plusieurs parties, l’eschatos représente la toute dernière partie de ce ruban. C’est d’ailleurs ce mot qui a donné naissance au terme « eschatologie », lequel désigne l'étude des choses dernières ou encore l’examen des événements qui précéderont le retour du Seigneur.\r\nSur le plan biblique et prophétique, l’eschatologie se définit comme l’étude de la dernière étape du “temps des nations” avant l'avènement du Seigneur. Elle s’inscrit donc dans la perspective de l'accomplissement dans la volonté d’Èlohiym révélé dans les Écritures.\r\n2. Quand la fin des temps a-t-elle débuté ?\r\nLa fin des temps a débuté avec la première venue du Seigneur sur la terre. En effet, les Écritures présentent la première venue et le sacrifice du Mashiyah comme le point de bascule vers cette ultime période. Ainsi, l’apôtre Petros (Pierre) le confirme en ces termes :\r\n« Sachant que ce n'est pas par des choses corruptibles - argent ou or que vous avez été rachetés hors de votre vaine manière de vivre que vos ancêtres vous avaient transmise, mais par un sang précieux, comme d'un agneau sans défaut et sans tache, Mashiah, prédestiné en effet avant la fondation du monde, et manifesté dans les derniers temps à cause de vous. » (1 Pierre 1 : 18-20 — BYM1).\r\n« L'Elohîm ayant autrefois parlé, à plusieurs reprises et de plusieurs manières par les prophètes, nous a parlé en ces derniers jours par le Fils, qu'il a établi héritier de toutes choses, par le moyen duquel aussi il a fait les âges. » (Hébreux 1 : 1-2 ).\r\nCes passages montrent que les “derniers temps” ont commencé avec la manifestation du Mashiyah. En d'autres termes, selon la perspective apostolique, la venue, la mort et la résurrection du Mashiyah inaugurent la période finale de l'histoire du salut. Dès lors, l’humanité est entrée dans cette phase ultime, dans l'attente de son accomplissement lors de son retour.\r\n3. Dans l'horloge prophétique, à quel temps sommes-nous ?\r\nSelon la chronologie prophétique des Écritures, nous vivons une époque de transition spirituelle majeure. Pour comprendre où nous nous situons, il convient de se référer au système horaire romain en vigueur à l’époque de Yehowshuw‘a ha-Mashiyah, qui divisait la nuit en quatre veilles distinctes (comme le confirme Marc 13 : 35-36). La nuit y est ainsi structurée :\r\n•\t1ère Veille (Veille du soir, 18h-21h) : Début de la nuit, correspondant au temps du coucher du soleil.\r\n•\t2ème Veille (Veille de minuit, 21h-00h) : Milieu de la première partie de la nuit.\r\n•\t3ème Veille (Chant du coq, 00h-3h) : Le cœur de la nuit, également appelé « minuit ».\r\n•\t4ème Veille (Veille du matin, 3h-6h) : Période qui précède immédiatement l’aube.\r\nC’est au cœur de cette chronologie qu’un cri dans les nations se fit entendre pour réveiller l’Épouse, ainsi qu'il est écrit :\r\n« Or au milieu de la nuit un cri est advenu : Voici l'époux qui vient ! Sortez à sa rencontre ! » (Matthieu 25 : 6).\r\nCe cri de minuit, qui marque l’entrée dans la 3ème veille, a mis l’histoire en marche vers son dénouement. Depuis cet événement spirituel, le temps a progressé. C’est dans cette perspective de progression que l’apôtre Paulus  s’adresse aux Romains pour indiquer que la nuit touche bientôt à sa fin. Spirituellement, nous avons désormais dépassé le milieu de la nuit pour nous situer à la charnière entre la fin de la 3ème veille et le début de la 4ème  veille. Le temps est désormais compté, la nuit est en train d'arriver à son terme :\r\n« La nuit est avancée et le jour s'est approché. Alors débarrassons-nous des œuvres de ténèbre et soyons revêtus des armes de lumière. » (Romains 13 : 12).\r\nAinsi, en voyant la nuit s’effacer pour laisser place à la veille du matin, nous pouvons pleinement réaliser à quel point nous sommes proches de la fin et de l’apparition du Seigneur Yehowshuw‘a ha-Mashiyah.\r\n4. Qu’est-ce que le temps des nations ?\r\nLe temps des nations peut être défini comme la période spécifique accordée par ’Èlohiym aux nations pour organiser et diriger le monde. Or, force est de constater que ce temps des nations est désormais sur le point de s’achever. Le Seigneur Yehowshuw‘a ha-Mashiyah dit au sujet du temps des nations :\r\n« Et ils tomberont à bouche d'épée, ils seront emmenés captifs parmi toutes les nations, et Yeroushalaim sera foulée aux pieds par les nations, jusqu'à ce que les temps des nations soient accomplis. » (Luc 21 : 24).\r\nLe mot « accomplis » vient du grec πληροω (pleroô), dont l’une des significations est « amener à la réalisation » c'est-à-dire à son terme. Cela signifie que le temps accordé aux nations touche bientôt à sa fin. Cependant, si ce constat était déjà vrai il y a deux mille ans, combien plus ce temps est-il aujourd'hui en train de parvenir à son accomplissement total ?\r\n\r\n5. Quand le temps des nations a-t-il commencé ?\r\nCette période a débuté avec le royaume de Bavèl (Babylone) sous le roi Nevukadnè’tstsar II après l’effondrement total du royaume de Yisra’él avec la déportation de la nation de Yéhoudah en 587/586 avant J.-C.\r\nEn effet, ’Èlohiym avait tissé une alliance éternelle avec le patriarche ’Avraham : « Je lève mon alliance entre moi, entre toi, et entre ta postérité après toi pour leurs générations, une alliance perpétuelle, pour devenir ton Elohîm et celui de ta postérité après toi. » (Genèse 17 : 7). \r\nPar cette alliance ’Èlohiym s'engageait à devenir l’Èlohiym des enfants de Yisra’él. Cependant, le choix d'Èlohiym n'était pas fortuit. En réalité, son dessein ultime était de devenir l’Èlohiym de toutes les nations car, depuis la chute du premier couple, les hommes adorent de nombreuses créatures qu'ils nomment « ’Èlohiym » au lieu d'adorer le Créateur béni éternellement.\r\nAinsi en devenant l’Èlohiym de Yisra’él, Il souhaitait faire de ce peuple la lumière et le modèle des nations. Son intention était donc d'attirer l'humanité entière à lui, afin de devenir non seulement l’Èlohiym de Yisra’él, mais aussi celui de toutes les nations. \r\nPour mettre à exécution Sa volonté, Il fit alors plusieurs promesses aux enfants de Yisra'él :\r\n• La supériorité sur les nations : \r\n« Et il arrivera que si tu écoutes, si tu écoutes la voix de YHWH, ton Elohîm, et que tu prennes garde de pratiquer tous ses commandements que je t'ordonne aujourd'hui, YHWH, ton Elohîm, te donnera la supériorité sur toutes les nations de la Terre. » (Deutéronome 28 : 1) ;\r\n\r\n• Un peuple mis à part : \r\n« Car tu es un peuple saint pour YHWH, ton Elohim. YHWH, ton Elohîm, t'a choisi pour que tu deviennes son peuple, sa propriété parmi tous les peuples qui sont sur les faces du sol. » (Deutéronome 7 : 6 ; Nombres 23 : 9 ; voir aussi Ésaïe 43 : 1, 15) ;\r\n• Les témoins d’Èlohiym :\r\n« Vous êtes mes témoins, — déclaration de YHWH —, et mon serviteur que j'ai choisi, afin que vous connaissiez et que vous croyiez en moi. Comprenez, moi, lui ! Avant mes faces il n'a pas été formé de El, et il n'y en aura pas après moi. C'est moi, c'est moi YHWH, à part moi, il n'y a pas de Sauveur. C’est moi qui ai annoncé, sauvé et fait entendre, - ce n'est pas un étranger parmi vous. Vous êtes mes témoins, — déclaration de YHWH -, que je suis El. Même avant les jours, je suis le même, et nul ne délivre de ma main. J'agirai, qui m'en empêchera ? » (Ésaïe 43 : 10-12 ; voir aussi 44 : 8-9) ;\r\n• Au service de YHWH : \r\n« Maintenant, si obéir, vous obéissez à ma voix et gardez mon alliance, vous deviendrez ma propriété parmi tous les peuples, car toute la Terre est à moi. Vous deviendrez pour moi un royaume de prêtres et une nation sainte. Voilà les paroles que tu diras aux fils d'Israël. » (Exode 19 : 5-6 ; Deutéronome 10 : 12-13 ; voir aussi Ésaïe 44 : 1-2) ;\r\n• La révélation de YHWH et Sa Parole :\r\n« Il t'a fait entendre sa voix des cieux pour t'instruire et il t'a montré son grand feu sur la Terre, et tu as entendu ses paroles du milieu du feu. » (Deutéronome 4 : 36).\r\n• Aussi, Il leur fit connaître sa Parole :\r\n« Il a fait connaître sa parole à Yaacov, ses statuts et ses ordonnances à Israël. Il n’a pas agi ainsi pour toutes les nations, et ses ordonnances, elles ne les connaissent pas. Allélou-Yah. » (Psaumes 147 : 19-20) \r\n« Grande de toute manière ! Premièrement parce que les oracles d'Elohîm leur ont été confiés en effet. » (Romains 3 : 2).\r\nMalgré ces privilèges, Yisra’él se rebella contre ’Èlohiym. Ce déclin spirituel commença lorsque le roi Shlomoh (Salomon) bâtit des autels à des divinités étrangères :\r\n« Et il arriva au temps de la vieillesse de Shelomoh, que ses femmes détournèrent son cœur après d'autres elohîm, et son cœur ne fut plus tout entier à YHWH son Elohîm comme avait été le cœur de David son père. Et Shelomoh alla après Astarté, la divinité des Sidoniens, et après Milcom, l'abomination des Ammonites. Shelomoh fit ce qui est mal aux yeux de YHWH et il ne suivit pas pleinement YHWH, comme David, son père. Et Shelomoh bâtit un haut lieu à Kemosh, l'abomination des Moabites, sur la montagne qui est vis-à-vis de Yeroushalaim et à Moloc, l'abomination des fils d'Ammon. Il en fit de même pour toutes ses femmes étrangères qui brûlaient de l’encens et sacrifiaient à leurs elohîm. » (1 Rois 11 : 4-8)\r\nC’est précisément cet égarement spirituel qui entraîna, par la suite, le schisme de Yisra’él à l’époque de son fils Rechav’am (Roboam), en 931 avant J.-C, en divisant le royaume en deux nations distinctes : le royaume de Yisra’él au Nord (10 tribus, capitale Samarie) avec 19 rois, et le royaume de Yéhoudah au sud (2 tribus, capitale Yeroushalaïm ) avec 19 rois dont une reine.\r\nAvec la nouvelle configuration de la terre de Yisra’él, chacun des royaumes s’organisa de son côté. Toutefois, le royaume de Yisra’él sombra rapidement dans l’idolâtrie sous l'influence de Yarav’am (Jéroboam), fils de Nebath (1Rois 12 : 25-33 ; 2 Rois 17 : 21). Cette idolâtrie allait devenir une voie funeste, « la voie de Yarav‘am » dans laquelle marchèrent tous les rois du Nord ainsi que certains des rois du sud. \r\nAprès de multiples interpellations des prophètes, la colère d’Èlohiym devint sans remède : Salmanazar V a commencé le siège de Samarie, mais c’était Sargon II qui paracheva la déportation des 10 tribus en ’Ashshuwr  (Assyrie) en 722/721 avant J.-C. (2 Rois 17 : 3-23).\r\nAprès la destruction du royaume du nord, le royaume de Yéhoudah subit un sort identique à cause des péchés de Menashshèh, malgré les réformes des bons rois de Yéhoudah. C’est sous Tsidqiyah (Sédécias), du temps du prophète Yirmeyah (Jérémie), que le roi de Bavèl entra dans Yeroushalaïm en 587/586 avant J.-C., détruisant le temple et la ville (2 Rois 25 : 1-21).\r\nParallèlement, le prophète Yehèq’él (Ézéchiel), exilé à Bavèl, vit en vision la Gloire de YHWH quitter le temple : \r\n« Les chérubins élevèrent leurs ailes, et les roues étaient vis-à-vis d'eux. La gloire de l'Elohîm d'Israël était sur eux, en haut. La gloire de YHWH monta d’au-dessus du milieu de la ville et se tint au-dessus de la montagne qui est à l'orient de la ville. » (Ézéchiel 11 : 22-23 ; voir aussi 10 : 3-4).\r\nCe départ symbolise la fin de l'hégémonie politique et spirituelle de Yisra’él, ouvrant la porte au pouvoir de direction accordé aux nations et ouvrant la porte aux nations pour qu'elles fassent partie du peuple d’Èlohiym au travers de l’Église  (Joël 3 : 1 ; Actes 2 : 17).\r\nPar cet acte, ’Èlohiym permit que son Salut, Yehowshuw‘a ha-Mashiyah, vienne jusqu’aux nations :\r\n« Je dis donc : Ont-ils trébuché afin de tomber ? Que cela n’arrive jamais ! Mais, par leur chute, il y a le salut pour les nations, pour les exciter à la jalousie. Or, si leur chute est la richesse du monde et leur amoindrissement la richesse des nations, combien plus leur plénitude ! » (Romains 11 : 11-12) ;\r\n« Car je ne veux pas, frères, que vous ignoriez ce mystère, afin que vous ne soyez pas sages à vos propres yeux : c’est qu’un endurcissement est arrivé en partie à Israël jusqu’à ce que la plénitude des nations soit entrée. » (Romains 11 : 25).\r\nNéanmoins, la passation officielle des clés de la gestion du monde de Yisra’él aux nations se produisit véritablement à Bavèl. En effet, une nuit, le roi Nevukadnè’tstsar recevra une vision qu’il fut incapable de se rappeler. Ce fut le prophète Daniy’él  qui lui révéla son songe et lui en donna l’interprétation (Daniel 2 : 31-35). Cette statue était composée de différents matériaux qui représentaient des royaumes qui se sont succédés (Daniel 2 : 36-45) : \r\n→ L’or : le royaume de Bavèl (Babylone)\r\n→ L’argent : le royaume Médo-Perse\r\n\r\n→ L’airain : le royaume Gréco-Macédonien\r\n\r\n→ Le fer : l’empire Romain\r\n\r\n→ Le fer mêlé à l’argile : les 10 royaumes (l’Europe divisée). \r\n→ La pierre : c’est le Royaume des Cieux\r\n\r\nDans la suite du songe, une pierre se détache d’une montagne, sans le secours d’aucune main, vient frapper la statue au niveau des pieds et la brise totalement pour devenir le Royaume des Cieux qui s’étendra sur toute la Terre habitée :\r\n« Tu regardais cela, jusqu'à ce qu'une pierre se détacha sans l'aide d'une main, frappa les pieds en fer et en argile de la statue et les brisa. Alors le fer, l'argile, le cuivre, l'argent et l'or, furent brisés ensemble et devinrent comme la paille de l'aire en été, que le vent transporte çà et là et nulle trace n'en fut retrouvée. Mais la pierre qui avait frappé la statue devint une grande montagne et remplit toute la terre. » (Daniel 2 : 34-35).\r\nLe prophète Daniy’él annonça ensuite au roi que l’Èlohiym des Cieux lui avait accordé la domination sur toutes les nations de la terre :\r\n« C'est là le rêve. Nous en dirons l'interprétation en face du roi. Roi, tu es le roi des rois, parce que l'Élahh des cieux t'a donné le royaume, le pouvoir, la force et l’honneur. Il a remis entre tes mains, en quelque lieu qu'ils habitent, les enfants des humains, les bêtes des champs et les oiseaux des cieux, et il t'a fait dominer sur eux tous. C'est toi qui es la tête en or. » (Daniel 2 : 36-38).\r\nC’est à ce moment précis qu’Èlohiym confie officiellement la direction du monde aux nations. Yisra’él qui devait en être la lumière et le modèle, se mit à marcher au rythme des nations. Yisra’él qui devait être la tête devint la queue (Deutéronome 28 : 44).\r\nII. LA STATUE DE DANIEL 2 : PANORAMA PROPHETIQUE DE L'HISTOIRE\r\n6. Quels sont les différentes significations de la statue ?\r\na. Un repère temporel : La statue indique le début et la fin du temps des nations. Il commence avec le Royaume de Bavèl au moment de la chute de Yisra’él jusqu’au retour du Seigneur pour son règne millénaire. Cette période s'étend sur près de 26 siècles.\r\nb. Le règne de l’esprit de l’anti-Mashiyah : Cette statue représente le règne de l’esprit de l’anti-Mashiyah qui a commencé jusqu'à sa venue physique, après l’enlèvement de l’Église. L’apôtre Yôhanan déclarait : \r\n« Enfants, c'est ici la dernière heure. Et comme vous avez entendu que l'Anti-Mashiah vient, maintenant aussi beaucoup d'anti-mashiah sont apparus. De là nous savons que c'est la dernière heure. » (1 Jean 2 : 18). \r\nEn effet, depuis que les nations ont reçu la direction du monde, ils ne pratiquent pas des œuvres de justice mais au contraire pratiquent des œuvres qui vont à l’encontre de la Parole d’Èlohiym :\r\n•\tBavèl adorait des faux ’èlohiym (Daniel 1 : 1-2 ; 3 : 1-7 ; 5 : 1-4) ;\r\n•\tLes Perses adoraient « Ahura Mazda » ;\r\n•\tLes Grecs avaient plusieurs « dieux » (Zeus, etc. — Actes 17 : 22-23) ;\r\n•\tLes Romains avaient récupéré les mêmes divinités grecques.\r\nEt jusqu’à ce jour, les peuples du monde adorent des divinités étrangères qui ne sont que des démons.\r\nLe concept d’Anti-Mashiyah qui renvoie à l’adversaire du Mashiyah pourrait aussi symboliser l’ensemble de valeurs, de comportements, de principes, d’enseignements et de pensées qui s’opposent à ’Èlohiym et sa Parole à l’exemple des déviations sexuelles comme l’homosexualité, fornication, le culte des hommes, la rébellion, la domination, l’esprit de contrôle, la théorie de l’évolution c’est-à-dire que l’être humain est le produit de l’évolution des espèces, le divorce, le spiritisme, le mysticisme, la sorcellerie, les œuvres traditions comme les Bwiti, la Manbandzi, le vaudou, la franc-maçonnerie, la fraternité blanche, la pornographie, les pédophilie etc. L’apôtre Paulos disait à Timotheos  :\r\n« Mais sache aussi ceci, que dans les derniers jours seront présents des temps difficiles à supporter. Car les humains seront amoureux d'eux-mêmes, aimant l'argent, fanfarons, orgueilleux, blasphémateurs, rebelles à leurs parents, ingrats, non saints, sans affection naturelle, sans loyauté, calomniateurs, sans auto-contrôle, cruels, opposés à la bonté et aux hommes bons, traîtres, précipités, enflés d'orgueil, amis des voluptés plutôt qu'amis d'Elohîm, ayant l'apparence de la piété, mais ayant renié sa puissance. Éloigne-toi aussi de ceux-là. » (2 Timothée 3 : 1-5).\r\n« Ils affirment être sages, ils sont devenus stupides, et ils ont changé la gloire de l'Elohîm incorruptible en la ressemblance d'image de l'être humain corruptible, et des oiseaux, et des quadrupèdes, et des reptiles. C'est pourquoi aussi l'Elohîm les a livrés, dans les désirs de leurs propres cœurs, à l'impureté pour déshonorer entre eux leurs propres corps, eux qui ont échangé la vérité d'Elohîm contre le mensonge et qui ont adoré et servi la créature, au lieu du Créateur, qui est béni pour les âges. Amen ! En raison de cela Elohîm les a livrés à leurs passions déshonorantes, car même les femelles parmi eux ont échangé les rapports sexuels naturels pour des relations contre nature. De même aussi les mâles, abandonnant non seulement les rapports sexuels naturels avec le sexe féminin, mais ils se sont embrasés dans leurs désirs les uns pour les autres, accomplissant des choses honteuses, mâle avec mâle, et recevant en eux-mêmes la juste et correcte récompense de leur égarement. » (Romains 1 : 22-27). \r\nLorsque l’Anti-Mashiyah viendra il sera non seulement le représentant du diable sur la terre mais l’incarnation vivante du mal et de toutes les formes rébellions.\r\nDans la Bible, plusieurs noms lui sont attribués :\r\n« Que personne ne vous trompe d'aucune manière, parce qu'il faut d'abord que vienne l'apostasie et que se révèle l'homme de péché, le fils de la perdition, l’adversaire et celui qui s’élève contre tout ce que l'on nomme Elohîm ou que l'on adore, il va jusqu'à s'asseoir comme Elohîm dans le temple d'Elohîm se montrant lui-même comme étant Elohîm. » (2 Thessaloniciens 2 : 3-4) ;\r\n« Enfants, c'est ici la dernière heure. Et comme vous avez entendu que l’Anti-Mashiah vient, maintenant aussi beaucoup d'anti-mashiah sont apparus. De là nous savons que c'est la dernière heure. » (1 Jean 2 : 18, 22 ; 4 : 3 ; 2 Jean 1 : 7) ;\r\n« Et je me tins debout sur le sable de la mer. Et je vis, montant de la mer une bête ayant sept têtes et dix cornes, et sur ses cornes dix diadèmes, et sur ses têtes un nom de blasphème. Et la bête que je vis était semblable à un léopard, et ses pieds comme ceux d'un ours, et sa bouche comme la bouche d'un lion. Et le dragon lui donna sa puissance, et son trône et une grande autorité. » (Apocalypse 13 : 1-2, 17 ; 19 : 20) ;\r\n« Et sur les dix cornes qui étaient sur sa tête, et sur l’autre qui était sortie et devant laquelle trois étaient tombées, sur cette corne qui avait des yeux, une bouche qui disait de grandes choses et une plus grande apparence que ses associées. » (Daniel 7 : 20) :\r\n• L’homme de péché : La Bible l’appelle, non pas l’homme pécheur, mais l’homme du péché c’est-à-dire que cet être est assimilé au péché. Ce qui fait de lui l’incarnation et personnification vivante du mal. Il sera le modèle en matière de péché pour une humanité déchue. Ainsi, tout être humain qui a pour valeur morale « le Péché » s’identifiera à lui, comme les chrétiens s’identifient au Mashiyah en tant qu’exemple de vie sainte.\r\n• Le fils de la perdition : De par son étymologie, le mot perdition vient du grec απωλεια (apôlehia) signifiant destruction. Ainsi cette expression nous parle-t-elle de celui qui sera détruit. Celui en qui il n’y a point de salut et qui conduira dans l’étang de feu et de soufre ceux qui le suivent.\r\n• L’adversaire : Tiré du grec ἀντίκειμαι (antikehimahi) signifiant : « s’opposer », « être l’adversaire de », « résister » ou « être contraire à ». Il est la figure emblématique du mal qui s’oppose à toutes les valeurs que Yehowshuw‘a ha-Mashiyah a instituées dans le monde. Son objectif est de retourner les hommes – ceux dont les noms n’ont pas été écrits dès la fondation du monde – contre leur Créateur.\r\n• Celui qui s’élève contre tout ce que l’on nomme Elohîm : Il va usurper la position d’Èlohiym pour s’élever au-dessus de toute forme d’Èlohiym. Il va se faire adorer par les habitants de la Terre (Apocalypse 13 : 1-3, 8).\r\n• L’Anti-Mashiah : Formé à partir du mot ַחיִשָמ– Mashiyach – « celui qui a reçu l’onction » ou « l’oint ». Dans l’Écriture, le Mashiyah est le roi de Yisra’él qui vient sauver son peuple. L’anti-Mashiyah est un être qui a reçu une onction ténébreuse et maléfique pour s’opposer au Seigneur et à sa Parole et afin d’entraîner les hommes à la perdition. Il sera le dirigeant des nations et incarnera le pouvoir politique et religieux.\r\n• Bête : La forme spirituelle de l’anti-Mashiyah qui est présenté sous la forme d’une créature ayant sept (7) têtes et dix (10) cornes : « La bête que je vis ressemblait à un léopard ; ses pieds étaient comme ceux d'un ours, et sa gueule comme une gueule de lion ». Cette créature représente à la fois l’anti-Mashiyah et son royaume »(Apocalypse 13 : 1-2).\r\n• La petite corne : Dans la Bible, la corne représente en même temps des royaumes (Daniel 8 : 20) et des rois (Daniel 7 : 24). C’est une représentation de l’anti-Mashiyah en tant que dirigeant qui combattra les saints pendant la Grande Tribulation.\r\n7. Les nations de la statue existent-elles encore ?\r\nBien évidemment que non. Cependant, elles trouvent un écho ou une succession géographique directe aujourd'hui :\r\n• La nation de Bavèl renaît sous la nation irakienne.\r\n• L’empire Médo-Perse est devenu l’Iran actuel des Mollahs.\r\n• L'empire Greco-Macédonien correspond à la Grèce moderne.\r\n• Selon certaines lectures prophétiques contemporaines, l’Union Européenne est vue comme L'empire romain qui renaît sous la forme d’une confédération.\r\n8. Pourquoi les pieds sont-ils en fer et en argile mêlés ?\r\n« La tête de cette statue était en or très fin, sa poitrine et ses bras, en argent, son ventre et ses cuisses, en cuivre, ses jambes étaient en fer et ses pieds étaient en partie en fer et en partie en argile. » (Daniel 2 : 32-33)\r\nCe passage trouve son explication dans l’interprétation du songe donné par Daniy’él au roi de Bavèl : \r\n« Puisque tu as vu que les pieds et les orteils étaient en partie en argile de potier et en partie en fer, ce royaume sera divisé, mais il y aura en lui quelque chose de la force du fer, parce que tu as vu le fer mêlé à l'argile de potier. Les doigts des pieds étaient en partie en fer et en partie en argile. Ce royaume sera en partie fort et en partie fragile. Puisque tu as vu le fer mêlé à l'argile de potier, ils seront mêlés à la semence humaine, mais ils ne seront pas unis l'un à l'autre de même que le fer ne se mêle pas à l'argile. » (Daniel 2 : 41-43).\r\n9. Que représentent les 10 orteils ?\r\nSur la statue du roi de Bavèl, les 10 orteils sont le prolongement de l’Empire Romain détruit. Ils sont en correspondance avec les 10 cornes et dix diadèmes de la bête d’apocalypse chapitre 13 : \r\n« Et je me tins debout sur le sable de la mer. Et je vis, montant de la mer une bête ayant sept têtes et dix cornes, et sur ses cornes dix diadèmes, et sur ses têtes un nom de blasphème. » (Apocalypse 13 : 1).\r\nCes nations sont représentées par 10 rois ou dirigeants puissants du monde qui seront très utiles à l’anti-Mashiyah pendant son règne. Au départ, ils n’auront pas de royaume propre, mais ils vont donner leur autorité à la bête : \r\n« Et les dix cornes que tu as vues sont dix rois qui n'ont pas encore reçu le royaume, mais qui reçoivent autorité comme rois pour une heure avec la bête. Ceux-ci ont un même avis, et ils donneront leur puissance et leur autorité à la bête. » (Apocalypse 17 : 12-13).\r\n10. Que représente la pierre détachée sans le secours d’aucune main ?\r\n« Tu regardais cela, jusqu'à ce qu'une pierre se détacha sans l'aide d'une main, frappa les pieds en fer et en argile de la statue et les brisa. Alors le fer, l'argile, le cuivre, l'argent et l'or, furent brisés ensemble et devinrent comme la paille de l'aire en été, que le vent transporte çà et là et nulle trace n'en fut retrouvée. Mais la pierre qui avait frappé la statue devint une grande montagne et remplit toute la terre. ». (Daniel 2 : 34-35).\r\n« Dans les jours de ces rois, l'Élahh des cieux suscitera un Royaume qui ne sera jamais détruit, et ce Royaume ne passera pas à un autre peuple. Il brisera et anéantira tous ces royaumes-là, et lui-même sera établi éternellement. C'est pourquoi, tu as vu que de la montagne, une pierre a été coupée sans l'aide d'une main et qu'elle a brisé le fer, le cuivre, l'argile, l'argent et l'or. Le grand Élahh a fait connaître au roi ce qui arrivera après cela. Or le rêve est véritable et son interprétation est certaine. » (Daniel 2 : 44-45).\r\nComme elle est présenté, cette pierre qui se détache sans le secours d’aucune main représente le Retour du Seigneur Yehowshuw‘a ha-Mashiyah qui vient sur la Terre pour établir son règne millénaire :\r\n« YHWH sortira et il combattra contre ces nations, comme il a combattu au jour de la bataille. Ses pieds se poseront sur le Montagne des Oliviers, qui est en face de Yeroushalaim, à l’orient. La Montagne des Oliviers se fendra par le milieu, d’est en ouest, en une très grande vallée : une moitié de la montagne reculera vers le nord, et l’autre moitié vers le midi. » (Zacharie 14 : 3-4) ;\r\n« Car il est juste devant Elohîm qu'il rende la tribulation à ceux qui vous oppressent, et à vous, qui êtes oppressés, le repos avec nous, dans la révélation du Seigneur Yéhoshoua du ciel avec les anges de sa puissance, dans une flamme de feu, exerçant la vengeance sur ceux qui ne connaissent pas Elohîm et sur ceux qui n'obéissent pas à l'Évangile de notre Seigneur Yéhoshoua Mashiah. » (2 Thessaloniciens 1 : 6-8) ;\r\n« Et alors sera révélé le violeur de la torah que le Seigneur détruira par l'Esprit de sa bouche et qu'il anéantira par l'apparition de sa parousie. » (2 Thessaloniciens 2 : 8) ;\r\n« Mais c'est aussi pour eux que Hanowk, le septième après Adam, a prophétisé, en disant : Voici, le Seigneur est venu avec la multitude innombrable de ses saints, pour exercer un jugement contre tous et pour convaincre tous les impies d'entre eux, de toutes leurs actions d'impiété qu'ils ont commises d'une manière impie, et de toutes les paroles injurieuses que les pécheurs impies ont proférées contre lui. » (Jude 1 : 14-15) ;\r\n« Et je vis le ciel ouvert, et voici un cheval blanc. Et celui qui est assis sur lui s'appelle Fidèle et Véritable, et c’est en justice qu’il juge et qu’il combat. Et ses yeux sont comme une flamme de feu et il y a sur sa tête beaucoup de diadèmes. Il a un nom écrit que personne ne connaît, excepté lui-même. Et il était revêtu d'un vêtement trempé de sang. Et son nom s'appelle : La Parole d'Elohîm. Et les armées qui sont dans le ciel le suivaient sur des chevaux blancs, revêtues de fin lin blanc et pur. Et depuis sa bouche sort une grande épée tranchante, afin qu’il en frappe les nations. Il les gouvernera avec un sceptre de fer, et il foulera aux pieds la cuve du vin de l'indignation et de la colère d'Elohîm, du Tout-Puissant. Et il a sur son vêtement et sur sa cuisse ce nom écrit : Roi des rois et Seigneur des seigneurs. » (Apocalypse 19 : 11-16).\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\nIII. Daniel 7 : La vision des quatre bêtes\r\n11. Que représentent les quatre bêtes de Daniel 7 et quels sont leurs caractères ?\r\nLa vision des quatre créatures extraordinaires montées de la grande mer  (la Méditerranée) constitue la contrepartie spirituelle des empires de la statue de Daniel 2 :\r\n• La première bête (Le lion ailé) : L'empire néo-babylonien (626-539 av. J.-C.). \r\n« La première était semblable à un lion, et avait des ailes d'aigle. Je la regardai jusqu'à ce que ses ailes furent arrachées. Elle fut soulevée de terre et mise debout sur ses pieds comme un être humain, et un cœur d'être humain lui fut donné. » (Daniel 7 : 4). \r\nLe lion ailé faisait partie de la mythologie mésopotamiens. Il symbolisait notamment chez les Sumériens et les Akkadiens : la force brute, la domination, la puissance souveraine, la victoire sur le chaos.\r\nCe royaume domina la région jusqu’à son renversement par l’empire Médo-Perse en 539 avant J.-C. :\r\n« Voici l'interprétation de ces paroles. Mené (Compté) : Élahh a fait les comptes de ton règne et y a mis fin. Teqel (Pesé) : tu as été pesé dans la balance et tu as été trouvé léger. Parsîn (Divisé) : ton royaume a été divisé et donné aux Mèdes et aux Perses.  Alors Belshatsar ordonna qu'on revête Daniye’l de pourpre, qu'on lui mette au cou un collier d'or et qu'on proclame qu'il deviendrait le troisième gouvernant dans le royaume. Cette même nuit, Belshatsar, roi des Chaldéens, fut tué. Darius, le Mède, reçut le royaume, étant fils de 62 ans. » (Daniel 5 : 26-6 : 1).\r\n• La deuxième bête (L’ours vorace) : L'empire Médo-Perse (559-331 av. J.-C.). \r\n« Et voici une autre bête, une seconde, semblable à un ours. Elle se tenait sur un côté, ayant trois côtes dans la gueule entre ses dents. On lui disait ainsi : Lève-toi, mange beaucoup de chair ! » (Daniel 7 : 5).\r\nContrairement à l’empire de Bavèl, l’ours n’était pas un symbole politico-religieux, mais il illustrait plutôt un caractère vorace et violent de cet empire.\r\n\r\nPlusieurs éléments sur la créature sont significatifs :\r\n• Elle se tenait sur un côté : Dans l’histoire, la puissance de ce royaume dépendait de l’équilibre entre deux peuples, dont l’un finit par dominer l’autre. En effet, lors de la guerre entre les Mèdes et les perses, Astyage, roi des Mèdes, fut vaincu par Cyrus le perse. Ce dernier : « mêla les coutumes et les lois des deux peuples, unit leurs royaumes et étendit leurs conquêtes. Bien que les Mèdes fussent vassaux des Perses, les deux peuples formaient un double empire. Ainsi, les Mèdes occupaient de hautes fonctions dans l’État et ils conduisaient les armées perses ; les étrangers parlaient des Mèdes et des Perses [...] ».\r\n• Trois côtes dans la gueule entre ses dents : Les trois (3) côtes dans la gueule de l’ours symbolisent les trois nations qui ont été vaincu par l’empire Médo-Persique : le royaume de Bavèl (conquis par le Cyrus le grand en 539 avant J.-C.), du royaume de la Lydie, également soumis par le Cyrus le grand et le royaume de l’Égypte (capitulation devant Cambyse II, fils de Cyrus le Grand en 525 avant J.-C.).\r\nLe royaume des Mèdes et des Perses tomba ensuite devant l’empire Greco-Macédonien d’Alexandre le Grand :\r\n« […] Je le vis arriver à proximité du bélier et manifester son amertume contre lui : il frappa le bélier et lui brisa les deux cornes, et le bélier n'avait aucune force pour se tenir debout face à lui. Il le jeta par terre et le piétina, et il n'y eut personne pour délivrer le bélier de sa main. Le bouc d'entre les chèvres grandit extrêmement, mais lorsqu'il fut puissant, sa grande corne se brisa. Quatre cornes considérables s'élevèrent pour la remplacer, aux quatre vents des cieux. » (Daniel 8 : 1-8) ;\r\n« Le bélier que tu as vu qui avait deux cornes, ce sont les rois des Mèdes et des Perses. Le bouc velu, c'est le roi de Yavan  . La grande corne entre ses yeux, c'est le premier roi. La brisée, à la place de laquelle les quatre se sont élevées, ce sont quatre royaumes. Elles s'élèveront de cette nation, mais qui n'auront pas autant de force. » (Daniel 8 : 20-23).\r\n• La troisième bête (Le léopard à quatre ailes et quatre têtes) : L’empire Gréco-Macédonien d'Alexandre le Grand (336-323 avant J.-C. ; Daniel 7 : 6 ; 8 : 1-8). \r\n« Après cela j'étais en train de regarder, et voici une autre bête, semblable à un léopard. Elle avait sur son dos quatre ailes d'oiseau, et cette bête avait quatre têtes, et la domination lui fut donnée. » (Daniel 7 : 6).\r\nLe léopard aux quatre (4) ailes sur le dos accentue cette image pour illustrer la vitesse fulgurante avec laquelle Alexandre le Grand a conquis le monde connu en seulement dix ans. \r\nPar ailleurs, les quatre têtes de la bête représentent ces quatre généraux qui se partagèrent son empire après sa mort précoce à Bavèl, à savoir :\r\n• Ptolémée Ier Sôter : Fondateur de la dynastie Lagide en Égypte ; \r\n• Séleucos Ier Nicator : Fondateur de l'Empire séleucide en Asie ;\r\n• Cassandre : Qui prit le contrôle de la Macédoine et de la Grèce ; \r\n• Lysimaque : Maître d'une grande partie de l'Asie mineure et Thrace.\r\n• La quatrième bête (La bête terrible aux dents de fer et 10 cornes) : L'empire Romain historique (27 av. J.-C. à 476 apr. J.-C.). \r\n« Après cela, j'étais en train de regarder dans mes visions nocturnes, et voici, il y avait une quatrième bête, effrayante, terrible et extraordinairement forte. Elle avait de grandes dents en fer. Elle mangeait, brisait et foulait aux pieds ce qui restait. Elle était différente de toutes les bêtes précédentes et avait dix cornes. » (Daniel 7 : 7).\r\nLa quatrième bête représente l’empire Romain. Cette créature porte sur elle dix cornes qui correspondent aux dix royaume barbares qui assiégèrent Rome et se partagèrent son territoire après ces incursions successives qui affaiblirent l’empire jusqu’à sa chute définitive de l’empire d’Occident en 476 après J.-C.\r\nCes nations barbares considérées comme les héritières de l'espace romain sont : \r\n1. Les Wisigoths (Espagne et Gaule du Sud)\r\n2. Les Ostrogoths (Italie)\r\n3. Les Francs (France/Gaule)\r\n4. Les Burgondes (Suisse/Est de la France)\r\n5. Les Alamans (Allemagne)\r\n6. Les Angles et les Saxons (Grande-Bretagne)\r\n7. Les Vandales (Afrique du Nord)\r\n8. Les Suèves (Portugal)\r\n9. Les Hérules, Skires et Ruges (coalition d'Odoacre qui dépose le dernier empereur en 476)\r\n12. Pourquoi la vision de Daniel 7 met-elle l'accent sur le caractère moral des royaumes ?\r\nL’objectif est de montrer le caractère bestial, violent, dévorant et oppressif que ces différentes nations manifestaient. En effet, ’Èlohiym montra au prophète Daniy’él l’aspect spirituel de ces royaumes :\r\n• Le royaume de Bavèl : Lion ailé\r\n• Le royaume Médo-Perse : L’ours qui se tenait sur un côté\r\n• Le royaume Gréco-Macédonien : Le léopard à quatre têtes\r\n• Le royaume romain : un monstre inidentifiable à dix cornes\r\n13. Qui est la petite corne et que symbolise-t-elle ?\r\n« Comme j'étais en train de considérer les cornes, voici, une autre petite corne sortit du milieu d'elles, et trois des premières cornes furent arrachées par elle. Et sur cette corne, il y avait des yeux comme des yeux d'être humain, et une bouche qui disait de grandes choses. » (Daniel 7 : 8).\r\nCette corne émerge au milieu des ruines de Rome, et porte deux caractéristiques : \r\n• Politique : la corne représente un royaume (Daniel 7 : 24), \r\n• Religieuse : les yeux et une bouche qui disait de grandes choses et fit la guerre aux saints (Daniel 7 : 21-22).\r\nHistoriquement et prophétiquement, l’émergence de la « petite corne » (Daniel 7 : 8, 24) est associée, dans le cadre de la grille d'interprétation prophétique dite historiciste, à l'essor d'un pouvoir religieux et politique établi sur les ruines de l’Empire romain d’Occident.\r\nLe texte biblique indique qu’une petite corne s’élève au milieu de dix cornes et qu’elle abaisse ou déracine trois rois (Daniel 7 : 8, 24).\r\n• Sur le plan historique et théologique : Un parallèle est traditionnellement fait entre ces trois cornes et trois royaumes germaniques établis sur les anciens territoires romains : les Hérules, les Vandales et les Ostrogoths. Ces trois peuples avaient pour point commun d’avoir adopté l’arianisme (une doctrine rejetant la divinité du Mashiyah affirmée au Concile de Nicée).\r\n• Sur le plan géopolitique : La disparition politique de ces trois royaumes au cours du VIème siècle s'est faite à travers les campagnes militaires de reconquête menées par l’Empire romain d’Orient sous l’empereur Justinien Iᵉʳ (527-565) — ainsi que par Théodoric le Grand concernant la chute de la domination de l’Hérule Odoacre en Italie.\r\n• Le lien prophétique : Dans la lecture historiciste des prophéties, l’effondrement de ces trois royaumes ariens (qui s’opposaient à l'autorité ecclésiastique de Rome) a directement ouvert la voie à la suprématie politique et spirituelle du pouvoir représenté par la petite corne en Occident.\r\nLe texte de Daniel déclare :\r\n« J'étais en train de regarder alors, à cause du son des grandes choses que disait la corne. Pendant que je regardais, la bête fut tuée, et son corps fut détruit et livré pour être brûlé au feu. » (Daniel 7 : 11).\r\nDans son contexte biblique, ce passage décrit la destruction de la quatrième bête dans la vision prophétique de Daniy’él.\r\n14. Qui est le Fils de l’homme recevant le royaume ?\r\nIl est question du Seigneur Yehowshuw‘a ha-Mashiyah. Dans les évangiles, l’appellation « le Fils de l’homme » utilisé pour le Seigneur est mentionné plus de 80 fois. Aussi, cette citation « le Fils de l’homme recevant le royaume », nous la retrouvons dans Luc 19 : 11-12 :\r\n« Or eux, en entendant ces choses, ajoutant, il dit une parabole, parce qu'il était près de Yeroushalaim, et qu'ils pensaient que le Royaume d'Elohîm allait immédiatement paraître. Il dit donc : Un homme noble s'en alla dans une contrée éloignée pour recevoir un royaume et revenir. ».\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\nIV. LA PERIODE FINALE : TRANSITION VERS L'ACCOMPLISSEMENT\r\n15. Y aura-t-il une confédération finale des nations ?\r\nDans le chapitre 13 d’Apocalypse 1 à 3 :\r\n« Et je me tins debout sur le sable de la mer. Et je vis, montant de la mer une bête ayant sept têtes et dix cornes, et sur ses cornes dix diadèmes, et sur ses têtes un nom de blasphème. Et la bête que je vis était semblable à un léopard, et ses pieds comme ceux d'un ours, et sa bouche comme la bouche d'un lion. Et le dragon lui donna sa puissance, et son trône et une grande autorité. ».\r\nCette créature représente à la fois deux réalités : l’anti-mashiyah et son système qui est formé de toutes les nations de la Terre dont l’anti-mashiyah sera à la tête. Ce sera un système politico-religieux mondial centré sur la bête et le faux prophète souvent est appelé dans le milieu évangélique « le gouvernement mondial ».\r\n« Et il lui fut donné de faire la guerre aux saints et de les vaincre. Il lui fut aussi donné autorité sur toute tribu, toute langue et toute nation. Et ils l'adoreront, tous les habitants de la Terre dont les noms n'ont pas été écrits dans le livre de vie de l'Agneau tué depuis la fondation du monde. » (Apocalypse 13 : 7).\r\nLe système économique mondial sera sous le contrôle total de l’anti-mashiyah :\r\n« Et elle fait qu'à tous, petits et grands, riches et pauvres, libres et esclaves, il soit donné une marque sur leur main droite ou sur leur front. Et que personne ne puisse acheter ou vendre, excepté celui qui a la marque, ou le nom de la bête ou le nombre de son nom. Ici est la sagesse : Que celui qui a de l'intelligence compte le nombre de la bête, car c'est un nombre humain. Et son nombre est 666. » (Apocalypse 13 : 16-18).\r\n16. Quel rôle joue l’anti-mashiyah dans la fin des temps ?\r\nLe rôle principal de l’anti-mashiyah est d’égarer tous les habitants — ceux les noms ne sont pas écrits dans le livre de vie de l’agneau (Apocalypse 13 : 8) — par toutes les tromperies de l’injustice : \r\n« Et alors sera révélé le violeur de la torah que le Seigneur détruira par l'Esprit de sa bouche et qu'il anéantira par l'apparition de sa parousie. Lui dont la parousie est selon l'efficacité de Satan, avec toute puissance, avec des signes et des prodiges de mensonge, et en toute tromperie d'injustice en ceux qui périssent parce qu'ils n'ont pas reçu l'amour de la vérité pour être sauvés. » (2 Thessaloniciens 2 : 8-9).\r\nIl a également pour but de pousser tous les habitants de la Terre à adorer le Dragon et la Bête.\r\nSon autre objectif est de révéler Satan à cette humanité déchue sous tous ces aspects, dans le seul but de retourner la créature contre son créateur. Il ira jusqu’à se faire passer pour ’Èlohiym afin d’être adoré comme ’Èlohiym par les habitants de ce monde : \r\n« L’adversaire et celui qui s’élève contre tout ce que l'on nomme Elohîm ou que l'on adore, il va jusqu'à s'asseoir comme Elohîm dans le temple d'Elohîm se montrant lui-même comme étant Elohîm. » (2 Thessaloniciens 2 : 4).\r\n\r\n\r\n\r\n17. Quels signes annoncent l’approche du retour de Mashiyah ?\r\nLa Bible dit :\r\n« Mais s'étant assis sur la Montagne des Oliviers, ses disciples vinrent à lui en particulier et lui dirent : Dis-nous quand ces choses arriveront-elles, et quel sera le signe de ta parousie et de l'achèvement de l'âge ? » (Matthieu 24 : 3).\r\nLe mot signe vient du grec σημειον (sème-ion) : « un signe, une marque, un témoignage ».\r\nNous allons citer quelques signes qui témoignent du Retour du Seigneur. Nos preuves seront puisées des évangiles Matthieu 24, Marc 13 et Luc 21. Pour une meilleure lecture et organisation des signes eschatologiques, nous allons ranger les signes en quatre grandes catégories :\r\nCette catégorie concerne le bouleversement des nations et de la création elle-même :\r\na. Les signes géopolitiques et environnementaux\r\nC’est le commencement des douleurs. La fin des temps est marquée par une instabilité dans plusieurs régions du monde :\r\n• Les guerres et les bruits de guerre : Une augmentation des conflits mondiaux.\r\n« Mais vous êtes sur le point d'entendre des guerres et des bruits de guerres : Faites attention ! Ne soyez pas troublés, car il faut que toutes ces choses arrivent, mais ce n’est pas encore la fin. Car nation se réveillera contre nation et royaume contre royaume […] » (Matthieu 24 : 6-7).\r\n• Les cataclysmes naturels : Une multiplication des crises environnementales et sanitaires dans divers endroits simultanément.\r\n« […] et il y aura des famines, des pestes et des tremblements de terre en divers lieux. » (Matthieu 24 : 7).\r\nb. Les signes religieux : Le faux réveil et l’apostasie :\r\nParallèlement aux multiplications des guerres, apparaîtra une profusion des faux mashiyah et de faux prophètes dont l’objectif est d’induire en erreur les enfants du Seigneur et refroidissement général de la foi : l’apostasie :\r\n• Les faux mashiyah : Le réveil des faux oints et des faux prophètes sur toute la planète Terre.\r\n« Et Yéhoshoua répondant, leur dit : Discernez ! Que personne ne vous égare, car beaucoup viendront sous mon nom, en disant : « Moi, je suis le Mashiah », et ils en égareront beaucoup. » (Matthieu 24 : 4-5, voir aussi 23-26). \r\nLe Seigneur a annoncé la venue des anti-mashiyah : En Côte d’Ivoire, un homme s’est fait passer pour le Seigneur Yehowshuw‘a ha-Mashiyah : « Nous n’en savons rien. Ils nous disent qu’il y a un collectif de pasteurs qui est venu de plaindre pour dire qu’ils ne sont d’accord sur le fait qu’il dise qu’il est Jésus d’une église  » \r\nEn Sibérie, un ancien policier affecté à la circulation, Sergueï Torop, a fondé en 1991 « Église du Dernier testament » dans la région de Krasnoïarsk, au sud de la Sibérie, alors que l’Union soviétique était en plein effondrement. Il s’est autoproclamé être la réincarnation du Christ .\r\n• L’apostasie : L’abandon massif de la Parole d’Èlohiym au profit des fausses doctrines\r\n« Et, parce que la violation de la torah sera multipliée, l'amour de beaucoup se refroidira. » (Matthieu 24 : 12 ; 1 Timothée 4 : 1) ;\r\n« Que personne ne vous trompe d'aucune manière, parce qu'il faut d'abord que vienne l'apostasie […] » (2Thessaloniciens 2 : 3) ;\r\n« Mais l'Esprit dit expressément que dans les derniers temps, certains s'éloigneront de la foi, s'attachant à des esprits trompeurs et à des doctrines de démons, » (1 Timothée 4 : 1).\r\nc. Les signes moraux et la persécution :\r\nL’état moral de l’humanité se dégrade de plus en plus, caractérisé par un égocentrisme extrême. Mais un rejet de la foi Judéo-chrétienne par la persécution des chrétiens dans le monde entier :\r\n• Les signes moraux :\r\nL’homme devient au fil des siècles immoral et perd toutes les bonnes valeurs et bonnes mœurs.\r\n« Mais sache aussi ceci, que dans les derniers jours seront présents des temps difficiles à supporter. Car les humains seront amoureux d'eux-mêmes, aimant l'argent, fanfarons, orgueilleux, blasphémateurs, rebelles à leurs parents, ingrats, non saints, sans affection naturelle, sans loyauté, calomniateurs, sans auto-contrôle, cruels, opposés à la bonté et aux hommes bons, traîtres, précipités, enflés d'orgueil, amis des voluptés plutôt qu'amis d'Elohîm, ayant l'apparence de la piété, mais ayant renié sa puissance. Éloigne-toi aussi de ceux-là. » (2 Timothée 3 : 1-5).\r\n• La persécution chrétienne :\r\nIl est question de toutes formes d’agression physique ou morale que les chrétiens vivent dans le monde entier. Selon le média chrétien Portes Ouvertes , il existe deux types de persécutions : la persécution étau (l’oppression morale) et la persécution marteau (l’agression physique). \r\n« Alors ils vous livreront à la tribulation et vous tueront. Et vous serez haïs de toutes les nations à cause de mon nom. Et alors beaucoup seront scandalisés, et ils se livreront les uns les autres et se haïront les uns les autres. » (Matthieu 24 : 9-10)\r\n« Mais tous ceux qui veulent vivre pieusement dans le Mashiah Yéhoshoua seront aussi persécutés. » (2 Timothée 3 : 12).\r\nd. Les signes prophétiques majeurs :\r\nCes sont d’autres signes qui alertent sur le Retour triomphant de Yehowshuw‘a ha-Mashiyah sur Terre pour son Règne de mille ans :\r\n• La proclamation mondiale de l’Évangile : ce signe se décompose en deux branches :\r\n• Proclamation pour le réveil de l’Église :\r\n« Or au milieu de la nuit un cri est advenu : Voici l'époux qui vient ! Sortez à sa rencontre ! »  (Matthieu 25 : 1-3)\r\n• Témoignage contre toutes les nations :\r\n« Et cet Évangile du Royaume sera prêché dans toute la terre habitée, pour servir de témoignage à toutes les nations et alors viendra la fin. » (Matthieu 24 : 12).\r\n• La restauration de Yisra’él et le Temple de Yeroushalaïm :\r\nL’Écriture nous informe qu’il y aura un 3ème Temple qui sera rebâtit dans lequel l’anti-mashiyah viendra s’installer pour s’auto-proclamer ’Èlohiym :\r\n« L’adversaire et celui qui s’élève contre tout ce que l'on nomme Elohîm ou que l'on adore, il va jusqu'à s'asseoir comme Elohîm dans le temple d'Elohîm se montrant lui-même comme étant Elohîm. » (2 Thessaloniciens 2 : 4) ;\r\n« Et l'on me donna un roseau semblable à une verge, en disant : Réveille-toi et mesure le temple d'Elohîm et l'autel, et ceux qui y adorent ! » (Apocalypse 11 : 1).\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\nV. L’ABOUTISSEMENT : LE ROYAUME ETERNEL\r\n18. Comment le Royaume d’Èlohiym remplace-t-il les royaumes humains ?\r\nSelon l’interprétation du songe du roi de Bavèl, la pierre qui se détache sans le secours d’aucune main, va détruire le système gouvernemental démoniaque dont l’homme impie sera à la tête, va devenir une grande montagne sur toute la Terre :\r\n« Tu regardais cela, jusqu'à ce qu'une pierre se détacha sans l'aide d'une main, frappa les pieds en fer et en argile de la statue et les brisa. Alors le fer, l'argile, le cuivre, l'argent et l'or, furent brisés ensemble et devinrent comme la paille de l'aire en été, que le vent transporte çà et là et nulle trace n'en fut retrouvée. Mais la pierre qui avait frappé la statue devint une grande montagne et remplit toute la terre. ». (Daniel 2 : 34-35).\r\nEt comme nous l’avons dit plus haut, il est question du Retour du Seigneur Yehowshuw‘a ha-Mashiyah sur la Terre pour son Règne de mille ans :\r\n« YHWH sortira et il combattra contre ces nations, comme il a combattu au jour de la bataille. Ses pieds se tiendront debout en ce jour sur la Montagne des Oliviers, qui est en face de Yeroushalaim, à l'orient. La Montagne des Oliviers se fendra par le milieu, d'est en ouest, en une très grande vallée : une moitié de la montagne reculera vers le nord, et l'autre moitié vers le midi. » (Zacharie 14 : 3-4 ; voir aussi Actes 1 : 9-12) ;\r\n« Mais c'est aussi pour eux que Hanowk, le septième après Adam, a prophétisé, en disant : Voici, le Seigneur est venu avec la multitude innombrable de ses saints, pour exercer un jugement contre tous et pour convaincre tous les impies d'entre eux, de toutes leurs actions d'impiété qu'ils ont commises d'une manière impie, et de toutes les paroles injurieuses que les pécheurs impies ont proférées contre lui. » (Jude 1 : 14-15) ;\r\n« Et je vis le ciel ouvert, et voici un cheval blanc. Et celui qui est assis sur lui s'appelle Fidèle et Véritable, et c’est en justice qu’il juge et qu’il combat. Et ses yeux sont comme une flamme de feu et il y a sur sa tête beaucoup de diadèmes. Il a un nom écrit que personne ne connaît, excepté lui-même. Et il était revêtu d'un vêtement trempé de sang. Et son nom s'appelle : La Parole d'Elohîm. Et les armées qui sont dans le ciel le suivaient sur des chevaux blancs, revêtues de fin lin blanc et pur. » (Apocalypse 19 : 11-14).\r\n19. Que signifie la pierre qui frappe la statue ?\r\nCela veut dire que le Seigneur détruira le règne de l’anti-mashiyah et son système lors de son Retour pour le souffle de sa bouche et l’éclat de sa Parousie : \r\n« Et alors sera révélé le violeur de la torah que le Seigneur détruira par l'Esprit de sa bouche et qu'il anéantira par l'apparition de sa parousie. » (2 Thessaloniciens 2 : 8).\r\n« Et depuis sa bouche sort une grande épée tranchante, afin qu’il en frappe les nations. Il les gouvernera avec un sceptre de fer, et il foulera aux pieds la cuve du vin de l'indignation et de la colère d'Elohîm, du Tout-Puissant. » (Apocalypse 19 : 15).\r\nLe Seigneur le fera saisir avec le faux-prophète pour être jeté dans le lac de feu et de soufre :\r\n« Et la bête fut prise, et avec elle, le faux prophète qui avait produit en sa présence les signes par lesquels il avait égaré ceux qui avaient pris la marque de la bête et adoré son image. Et ils furent tous les deux jetés vivants dans le lac de feu brûlant, dans le soufre. » (Apocalypse 19 : 20).\r\n20. Quel est le lien entre les prophéties de Daniel et l'Apocalypse ?\r\nPlusieurs des prophéties de Daniy’él se retrouve dans le livre d’Apocalypse qui les complètent, les enrichit et donne une plus grande visibilité en particulier celles des chapitres 2, 7, 8, 9, 11 et 12. L’apôtre Yôhanan (Jean), sous l’inspiration du Saint-Esprit, utilise le même langage symbolique et les mêmes thèmes pour décrire les événements de la fin des temps.\r\nPour illustrer nos argumentaires, nous faisons un comparatif entre les deux livres :\r\na. Les royaumes humains et le Royaume éternel d’Èlohiym\r\n• Daniel 2 : La grande statue aux différents métaux (or, argent, bronze, fer, argile) représente les empires successifs. La pierre qui se détache sans le secours d’aucune main détruit toute la statue et devient une grande montagne qui remplit la terre (Daniel 2 : 34-35, 44).\r\n• Apocalypse : Dans le livre de l’Apocalypse, lors de son Retour, le Mashiyah détruira les nations rebelles et établit Son règne (Apocalypse 19 : 11-21 ; 20 : 4-6). La bête et les rois de la terre sont vaincus, et le Royaume d’Èlohiym s’étendra sur toute la Terre à partir de Yeroushalaïm.\r\nb. Les quatre bêtes et la bête finale\r\n• Daniel 7 : Quatre bêtes sortent de la mer. La quatrième est terrible, avec dix cornes. Une petite corne surgit, parle contre le Très-Haut, persécute les saints pendant « un temps, des temps et la moitié d’un temps » (Daniel 7 : 8, 24-25).\r\n• Apocalypse 13 : La bête qui monte de la mer a dix cornes et sept têtes. Elle blasphème contre ’Èlohiym, fait la guerre aux saints et exerce son autorité pendant 42 mois (Apocalypse 13 : 1-7). Le parallèle est très clair : la bête de l’Apocalypse est la manifestation finale de la quatrième royaume ressuscitée : la petite corne que vit Daniy’él.\r\nc. Le Fils de l’homme et le jugement\r\n• Daniel 7 : 13-14 : « J'étais en train de regarder dans ces visions de la nuit, et voici qu'avec les nuées des cieux venait comme un Fils d'humain. Il arriva jusqu'à l'Ancien des jours, et on le fit approcher de lui. Et il lui donna la domination, l'honneur et le règne. Tous les peuples, les nations et les langues le serviront. Sa domination est une domination éternelle qui ne passera pas, et son règne ne sera jamais détruit. »\r\n• Apocalypse : Cette figure revient plusieurs fois : « Voici, il vient avec les nuées. Et tout œil le verra, même ceux qui l'ont percé, et toutes les tribus de la Terre se frapperont la poitrine de chagrin à cause de lui. Oui, amen ! » (Apocalypse 1 : 7) ; le cavalier fidèle et véritable qui juge et combat (Apocalypse 19 : 11-16) ; et le Fils de l’homme qui moissonne la terre (Apocalypse 14 : 14).\r\nd. La période de tribulation et le temps prophétique\r\n• Daniel 7 : 25 ; 12 : 7 : « Un temps, des temps et la moitié d’un temps » (3,5 années ou 1260 jours).\r\n• Apocalypse : Même durée exprimée de plusieurs façons : 42 mois (Apocalypse 13 : 5), 1260 jours (Apocalypse 11 : 3 ; 12 : 6), ou « un temps, des temps et la moitié d’un temps » (Apocalypse 12 : 14).\r\ne. La résurrection et le jugement final\r\n• Daniel 12 : 1-3 : Les deux grandes résurrections des morts (« les uns pour la vie éternelle, les autres pour l’opprobre »).\r\n• Apocalypse 20 : La première résurrection pour le règne de mille ans, puis la résurrection finale pour le jugement du grand trône blanc.\r\n21. Comment les croyants doivent-ils vivre à la lumière de ces prophéties ?\r\nSuite à toutes ces prophéties, les chrétiens doivent vivre leur vie chaque jour comme si c’était le dernier car personne ne sait lorsque le Maître viendra prendre ses élus au jour de l’Enlèvement de l’Église. Ils doivent demeurer constamment dans une vie de sainteté :\r\n« Mais concernant les temps et les mesures de temps, frères, vous n'avez pas besoin qu'on vous en écrive, car vous savez vous-mêmes précisément que le jour du Seigneur vient comme un voleur dans la nuit. » (1 Thessaloniciens 5 : 1-2)\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\nNous espérons que cet article vous a encouragé et a fortifié votre foi. Que toute la Gloire soit rendue au Seigneur qui donne la semence au semeur. Vu les temps dans lesquels nous sommes, ne soyons pas distraits, mais fixons les yeux vers le Seigneur, car l’Église sera vraiment enlevée.\r\nPaix et bénédiction sur vous. Shalôm à tous !\r\n\r\n");

window.ARTICLES_CONTENU["La doctrine des baptêmes"] = window.formaterArticleTexte("Bonjour, bonsoir à tous,\r\n\r\nGénéralement lorsque nous entendons parler du baptême, la première idée qui surgit dans notre esprit est l’immersion d’une personne dans des eaux en guise d’acceptation de la foi en Yehowshou‘a ha-Mashiya’h (Jésus-Christ). Cependant, d’après la Bible, le baptême ne se résume pas seulement à cette action. En effet, la Bible nous parle de « La doctrine des baptêmes » selon Hébreux 6 : 2. Ainsi, l’emploi de ce pluriel sous-entend qu’il existe plusieurs types de baptêmes, plus précisément trois.\r\n\r\nNotre objectif est de vous aider par la grâce du Seigneur Yehowshou‘a ha-Mashiya’h, à comprendre ce que la Bible entend réellement par cette « doctrine des baptêmes ».\r\n\r\n## Qu’est-ce que le baptême ?\r\n\r\nLe mot « baptême » vient du grec βαπτισμα baptisma (bap’-tis-mah), qui est traduit littéralement par « immersion » ou « submersion ». Le baptême désigne donc fondamentalement est l’action d’immerger ou « plonger quelque chose dans ».\r\n\r\nD’après la doctrine apostolique, il existe trois formes de baptêmes : le baptême dans le Saint-Esprit, le baptême dans l’eau et le baptême dans le feu.\r\n\r\n## S’il existe trois types de baptêmes, pourquoi le prophète Yôhanan baptisait-il ?\r\n\r\nDès les premiers chapitres des quatre évangiles, nous découvrons le prophète Yôhanan (Jean) le Baptiste annonçant la venue du Royaume des Cieux et appelant les hommes à la repentance :\r\n\r\n« Or en ces jours-là arrive Yohanan le Baptiste, prêchant dans le désert de la Judée, et disant : Repentez-vous, car le Royaume des cieux s’est approché » (Matthieu 3 : 1-2_BYM[[FN:1]]).\r\n\r\nAinsi, ceux qui acceptaient son message venaient se faire baptiser :\r\n\r\n« Alors Yeroushalaim, toutes la Judée et toute la région environnante du Yarden se rendaient auprès de lui. Et, confessant leurs péchés, ils se faisaient baptiser par lui dans le Yarden » (Matthieu 3 : 5-6 ; voir aussi Marc 1 : 4-5 ; Luc 3 : 1-3 ; Jean 1 : 19-28).\r\n\r\nEn réalité, le baptême que le prophète Yôhanan le Baptiste administrait était un baptême de repentance destiné à préparer le cœur des hommes à recevoir le Mashiya’h (le Messie) :\r\n\r\n« Car c’est celui dont Yesha’yah, le prophète, a parlé en disant : C’est ici la voix de celui qui crie dans le désert : Préparer le chemin du Seigneur, aplanissez ses sentiers (Matthieu 3 : 3).\r\n\r\nDe ce fait, ce baptême était salutaire tant que Yehowshuw‘a ha-Mashiyah n’avait pas officiellement commencé son service auprès des enfants de Yisra’él. En d’autres termes, celui qui croyait en ’Èlohiym, à cette époque, et se faisait baptiser par Yôhanan était sauvé. Cependant, lorsque les pharisiens et les docteurs de la Tôrah ont refusé de se faire baptiser par le prophète Yôhanan, ils ont rendu nul le dessein d’Èlohiym à leur égard :\r\n\r\n« Et tout le peuple qui entendait cela, et les publicains justifiaient Elohîm, ayant été baptisés du baptême de Yohanan. Mais les pharisiens et les docteurs de la Torah, en ne se faisant pas baptiser par lui, ont rejeté le dessein d’Elohîm à leur égard (Luc 7 : 29-30).\r\n\r\n## Pendant combien de temps le baptême de Yôhanan le baptiste était-il valide ?\r\n\r\nLe baptême de Yôhanan le Baptiste a conservé sa fonction préparatoire jusqu\u0027à la manifestation officielle Yehowshou‘a ha-Mashiya’h et à l’accomplissement :\r\n\r\nEn effet, lorsque Yehowshou‘a est venu à lui, Yôhanan la supériorité du Mashiya’h\r\n\r\n« Alors, Yéhoshoua arrive de Galilée au Yarden vers Yohanan, pour être baptisé par lui. Mais Yohanan l’en empêchait en disant : C’est moi qui ai besoin d’être baptisé par toi, et tu viens à moi ! Mais répondant, Yéhoshoua lui dit : Laisse faire maintenant, car c’est ainsi qu’il nous convient d’accomplir toute justice. Et alors il le laisse faire (Matthieu 3 : 13-15).\r\n\r\n« Le lendemain, Yohanan voit Yéhoshoua venant à lui, et il dit : Voici l’Agneau d’Elohîm qui ôte le péché du monde » (Yohanan [Jean] 1 : 29).\r\n\r\nDès lors, ayant identifié publiquement le Fils d’Èlohiym, Yôhanan a naturellement orienté les hommes vers le Mashiya’h, marquant ainsi l’aboutissement de son ministère :\r\n\r\n« Le lendemain, Yohanan était encore là avec deux de ses disciples. Et, ayant regardé Yéhoshoua qui marchait, il dit : Voici l’Agneau d’Elohîm ! Et les deux disciples l’entendirent tenant ce discours, et ils suivirent Yéhoshoua » (Yohanan [Jean] 1 : 35-37).\r\n\r\n## Qu’est-ce que le baptême dans le Saint-Esprit ?\r\n\r\nLe baptême dans le Saint-Esprit désigne la naissance d’en-haut (la Nouvelle Naissance). Il s’agit de suivre le Seigneur Yehowshuw‘a ha-Mashiyah tout en renonçant à sa vie après s\u0027être sincèrement repentie devant lui et avoir confessé ses péchés.\r\n\r\nEn effet, lorsqu’une personne reçoit l’Évangile du Royaume des Cieux[[FN:2]] et croit en son cœur, il est regénéré : il devient une nouvelle créature et enfant d’Èlohiym Yehowshuw‘a ha-Mashiyah :\r\n\r\n« En quoi vous êtes aussi, après avoir entendu la parole de la vérité, l’Évangile de votre salut, en lui vous avez cru et vous avez été marqués du sceau du Saint-Esprit de la promesse » (Éphésiens 1 : 13 ; Jean 1 : 12-14 ; Jacques 1 : 18 ; 2 Corinthiens 5 : 17).\r\n\r\nPar conséquent, cette conversion véritable arrache le croyant du royaume des ténèbres pour le faire rentrer dans le Royaume de la Lumière :\r\n\r\n« Rendant grâce au Père, qui nous a rendus capables d’avoir par au lot des saints dans la lumière, qui nous a délivrés de l’autorité de la ténèbre, et nous a transportés dans le Royaume du Fils de son amour, en qui nous avons la rédemption par le moyen de son sang, le pardon des péchés » (Colossiens 1 : 12-14).\r\n\r\nAinsi, par cette immersion spirituelle, le nouveau croyant en Yehowshuw‘a ha-Mashiyah est pleinement intégré au Corps de Mashiyah et devient membre de la famille d’Èlohiym :\r\n\r\n« Car nous avons tous été baptisés dans un seul Esprit pour être un seul corps, soit juif, soit Grec, soit esclave, soit libre, et nous avons tous été abreuvés pour être un seul esprit (1 Corinthiens 12 : 13)\r\n\r\n« Ainsi donc, vous n’êtes plus des étrangers ni des gens sans citoyenneté, mais concitoyens des saints et membres de la famille d’Elohîm » (Éphésiens 2 : 19).\r\n\r\n## Être baptisé dans le Saint-Esprit, est-ce parler en langue ?\r\n\r\nMalheureusement, non. Cette doctrine — très répandue dans les milieux pentecôtistes et charismatiques — est apparue au début du XXe siècle. Elle trouve ses racines historiques dans le réveil d\u0027Azusa Street à Los Angeles (1906), dirigé par le pasteur afro-américain William J. Seymour.\r\n\r\nEn effet, lors des premières réunions de ce réveil, plusieurs participants ont reçu la manifestation du parler en langues avant même que Seymour ne l\u0027expérimente lui-même. Cependant, c\u0027est au prédicateur Charles Parham que l\u0027on doit la formulation stricte de cette doctrine, selon laquelle le parler en langues serait le signe initial obligatoire pour quiconque est baptisé dans le Saint-Esprit. Or, William J. Seymour s\u0027est opposé aux dérives de cet enseignement, estimant qu\u0027il ne reposait pas sur un fondement biblique équilibré. Cette théologie s\u0027est néanmoins diffusée à travers le monde par l\u0027entremise de divers mouvements pentecôtistes et charismatiques.\r\n\r\nD’après la Bible, cette doctrine ne peut pas être soutenue parce que le parler en langue est un don spirituel au même titre que les autres dons accordés par le Saint-Esprit. Ce don est distribué selon la volonté de l’Esprit d’Èlohiym et l’homme ne peut rien faire, ni prier ni jeûner pour l’obtenir si le Seigneur n’a prévu de le lui donner. Il est question ici de la souveraineté de Yehowshou‘a ha-Mashiya’h :\r\n\r\n« Mais un seul et même Esprit opère toutes ces choses, distribuant à chacun en particulier comme il veut » (1 Corinthiens 12 : 11).\r\n\r\nDe plus, pour appuyer cette thèse, l’apôtre Paulus[[FN:3]] pose une série de questions oratoires auxquelles tout le monde est appelé à répondre en toute objectivité, pour montrer que tout le monde ne peut pas nécessairement manifester les mêmes charismes. L’Église est un corps composé de différents membres (1 Corinthiens 12 : 14-27) :\r\n\r\n« Et Elohîm a en effet placé dans l’Assemblée premièrement des apôtres, deuxième des prophètes, troisième des docteurs, ensuite des miracles, puis des dons de guérisons, de secours, des gouvernements, des langues diverses. Tous sont-ils apôtres ? Tous sont-ils prophètes ? Tous sont-ils docteurs ? Tous ont-ils le don des miracles ? Tous ont-ils les dons de guérison ? Tous parlent-ils en langues ? Tous interprètent-ils ? » (1 Corinthiens 12 : 28-30).\r\n\r\nAinsi, la conversion ne peut être assimilée à la manifestation du parler en langue ou autres dons spirituels. Selon les Écritures, la véritable preuve d\u0027une vie transformée par la présence de l\u0027Esprit ne réside pas dans la manifestation des charismes, mais dans le fruit de l\u0027Esprit et la recherche de la sanctification (Galates 5 : 22 ; voir aussi Hébreux 12 : 14).\r\n\r\n## Qu’est-ce que le baptême dans l’eau ?\r\n\r\nLe baptême dans l’eau est l’immersion totale du nouveau croyant en Yehowshou‘a ha-Mashiya’h dans les eaux[[FN:4]]. Cet acte témoigne de l’engagement de foi envers notre ’Èlohiym Yehowshou‘a ha-Mashiya’h, comme l’explique l’apôtre Pierre :\r\n\r\n« C’était une imitation du baptême, qui n’est pas la purification des souillures de la chair, mais la demande faite à Elohîm d’une bonne conscience, et qui maintenant nous sauve par le moyen de la résurrection de Yéhoshoua Mashiah (1 Pierre 3 : 21).\r\n\r\nEn effet, l’action d’immerger entièrement une personne dans l’eau puis de l’en faire sortir, symbolise spirituellement la mort à l’ancienne vie de péché et la résurrection pour une vie nouvelle en Yehowshou‘a ha-Mashiya’h (le fait d’être sortit des eaux) :\r\n\r\n« Que dirons-nous donc ? Resterons-nous dans le péché afin que la grâce se multiplie ? Que cela n’arrive jamais ! Nous qui sommes morts au péché, comment vivrons-nous encore en lui ? Ignorez-vous que nous tous qui avons été baptisés en Mashiah Yéhoshoua, avons été baptisés en sa mort ? Nous avons donc été ensevelis avec lui par le moyen du baptême en sa mort, afin que, comme Mashiah est ressuscité des morts par la gloire du Père, de même nous aussi nous marchions en nouveauté. » (Romains 6 : 1-4 ; voir aussi Colossiens 2 : 12).\r\n\r\n## Qui a le droit de baptiser ?\r\n\r\nLes Écritures nous révèlent que l’administration du baptême n’était pas réservée exclusivement au Seigneur Yehowshou‘a ha-Mashiya’h lui-même, mais qu’elle était accomplie par ses disciples :\r\n\r\n« Quand donc le Seigneur sut que les pharisiens avaient entendu dire : Yéhoshoua fait et baptise plus de disciples que Yohanan, toutefois Yéhoshoua ne baptisait pas lui-même, mais c’étaient ses disciples, il quitta la Judée et retourna encore en Galilée. » (Jean 4 : 1-3).\r\n\r\nDe plus, cette mission a été formellement confirmée par ’Adonay Yehowshou‘a ha-Mashiya’h à l’ensemble de ses disciples avant son ascension :\r\n\r\n« Allez donc et faites de toutes les nations des disciples, les baptisant dans le Nom du Père, du Fils et du Saint-Esprit, leur enseignant à garder tout ce que je vous ai ordonné. Et voici, je suis avec vous tous les jours jusqu’à l’achèvement de l’âge. Amen ! » (Matthieu 28 : 19-20 ; voir aussi Marc 16 : 15-16 ; Actes 2 : 37-41 ; 8 : 12-13, 26-40 ; 9 : 17-18 ; 10 : 44-48).\r\n\r\n## Les femmes peuvent-elles baptiser ?\r\n\r\nCette question est sujette à de nombreuses controverses dans les milieux évangéliques. Cependant, lorsqu’on examine attentivement les Écritures, la réponse est affirmative : toute femme croyante a le droit de baptiser, dans la mesure où elle est elle-même un disciple de Yehowshou‘a ha-Mashiya’h.\r\n\r\nEn effet, le mandat de la grande commission (Matthieu 28 : 19) n’est pas restreint aux seuls apôtres ou aux responsables d’assemblées ; il est plutôt réservé aux disciples[[FN:5]] du Seigneur. Par conséquent, comme les femmes font partie des disciples du Seigneur alors elles peuvent, elles aussi baptiser (comme Tabitha dans Actes 9 : 36). Les empêcher, se serait mettre instaurer un esprit sectaire et religieux qui veut continuer à donner la prédominance aux hommes. Or devant le Seigneur nous sommes tous égaux.\r\n\r\nPar ailleurs, l\u0027apôtre Paulus rappelle qu\u0027en matière d’identité spirituelle et de salut devant ’Èlohiym, il n\u0027existe aucune distinction de privilège entre les sexes :\r\n\r\n« Il n’y a plus ni Juif ni Grec ; il n’y a plus ni esclave ni libre ; il n’y a plus de mâle et de femelle, car tous vous êtes un en Mashiah Yéhoshoua. » (Galates 3 : 27-28).\r\n\r\nDans ce passage, l’apôtre Paulus s’adresse-t-il seulement aux femmes ? L’Église de Corinthe est-elle composée uniquement de femmes ? Bien sûr que non. L’apôtre veut montrer que l’Église, qui est une assemblée d’hommes et de femmes, est en fait une femme, l’épouse du Mashiya’h. Ainsi, si l’Église est une femme, peut-on refuser aux femmes chrétiennes de pouvoir baptiser ? Bien entendu que non.\r\n\r\n## Peut-on baptiser les enfants ?\r\n\r\nC\u0027est un sujet d\u0027une importance capitale qui suscite des débats depuis des siècles, notamment depuis la Réforme protestante du XVIᵉ siècle entre Martin Luther et Ulrich Zwingli apr. J.-C.\r\n\r\nCe sujet avait même entraîné une vive discussion entre Martin Luther et Ulrich Zwingli, lui aussi réformateur. Même si la Bible ne présente aucun exemple de baptême de nourrissons, elle enseigne clairement qu\u0027au jugement dernier, des personnes de tout âge comparaîtront pour répondre de leurs actes :\r\n\r\n« Et je vis un grand trône blanc et celui qui est assis dessus. Le ciel et la terre s’enfuirent de devant sa face et l’on ne trouva plus de place pour eux. Et je vis les morts, les grands et les petits, qui se tenaient devant Elohîm. Des livres furent ouverts. Et un autre livre fut ouvert, celui qui est le livre de vie. Et les morts furent jugés d’après les choses écrites dans les livres, selon leurs œuvres » (Apocalypse 22 : 11-12).\r\n\r\nEn effet, la Bible dit que toutes les personnes présentes en ce jour seront jugées selon leurs œuvres. Parmi ces personnes, figureront « les petits », c’est-à-dire les enfants qui seront condamnés. Ces enfants seront condamnés parce qu’ils auront déjà su faire la différence entre le bien et le mal. Donc en mesure de rejeter le bien, accepter et suivre la voie du mal et inversement. La Parole d’Èlohiym dit :\r\n\r\n« La folie est liée au cœur du jeune enfant, mais la verge de la correction l’éloignera de lui » (Proverbes 22 : 15).\r\n\r\nL\u0027Histoire biblique en donne un exemple concret :\r\n\r\n« Yehoyakin était âgé de 8 ans quand il devint roi, et il régna 3 mois et 10 jours à Yeroushalaim. Il fit ce qui est mal aux yeux de YHWH (2 Chroniques 36 : 9).\r\n\r\nA cette époque, l’expression « faire ce qui est mal aux yeux de YHWH » était synonyme de suivre la voie de Yarov‘am, fils de Nebath, c’est-à-dire vouer un culte à de faux ’èlohiym.\r\n\r\nEn conclusion, si des enfants seront devant le grand trône blanc pour le jugement dernier, alors un enfant peut décider de suivre ’Èlohiym Yehowshou‘a ha-Mashiya’h comme Seigneur et Sauveur, se faire baptiser et sauver son âme des tourments éternels. En revanche, le baptême des nourrissons (incapables de croire) ne trouve aucun fondement dans la doctrine des apôtres.\r\n\r\n## Les cours de baptême sont-ils bibliques ?\r\n\r\nLes cours de baptême prolongés, lorsqu’ils sont imposés comme condition obligatoire avant de pouvoir être baptisé, ne reposent sur aucun modèle explicitement établi dans les Écritures. En effet, dans le livre des Actes, le baptême suit généralement de très près la repentance, la réception de la Parole et la foi en Yehowshou‘a ha-Mashiya’h.\r\n\r\nCela ne signifie toutefois pas que l’instruction du nouveau croyant soit anti-biblique, puisque l’annonce et l’explication de la Parole précèdent naturellement la foi et le baptême dans plusieurs récits. Ainsi, avant de baptiser l’eunuque éthiopien, Philippos lui annonça Yehowshou‘a à partir des Écritures (Actes 8 : 30-38). De même, Paulus et Silas annoncèrent la Parole du Seigneur au geôlier de Philippes et à tous ceux qui étaient dans sa maison avant qu’ils soient baptisés (Actes 16 : 30-33).\r\n\r\nLa question essentielle n’est donc pas de savoir si une personne a atteint un certain niveau de perfection spirituelle, mais s’il a véritablement reçu la Parole, s’est tourné vers Èlohiym en se repentant de ses péchés et a placé sa foi en Yehowshou‘a ha-Mashiya’h.\r\n\r\nAucun être humain ne peut exiger d’un candidat au baptême qu’il soit devenu exempt de tout avant de recevoir le baptême péché. En effet, 1 Jean 1 : 8-10 enseigne que, si nous disons que nous n’avons pas de péché, nous nous séduisons nous-mêmes et que la vérité n’est pas en nous.\r\n\r\nLe baptême n’est donc pas la récompense d’une personne devenue parfaite ; mais l’engagement d’une personne qui s’est tourné vers le Seigneur.\r\n\r\nDans plusieurs récits du livre des Actes, ceux qui reçurent la Parole furent baptisées sans qu’une longue période de probation soit mentionnée :\r\n\r\n« Ceux donc qui acceptèrent sa parole avec joie furent en effet baptisés. Et environ 3000 âmes furent ajoutées ce jour-là » (Actes 2 : 41 ; voir aussi 8 : 12-13, 26-40 ; 9 : 17-18 ; 10 : 44-48 ; 16 : 30-33 ; 19 : 1-5).\r\n\r\nÀ la Pentecôte, environ trois mille baptêmes furent baptisés le jour même où elles reçurent la prédication de l’Évangile (Actes 2 : 37-41). L’eunuque éthiopien fut baptisé dès qu’il rencontra de l’eau après avoir entendu l’Évangile de Yehowshou‘a (Actes 8 : 35-39). Le geôlier de Philippes et les siens furent baptisés « immédiatement », au cours de la même nuit après avoir entendu la Parole du Seigneur (Actes 16 : 30-33). Quant aux disciples rencontrés par Paulus[[FN:6]] à Éphèse, ils furent baptisés après avoir entendu son enseignement concernant Yehowshou‘a (Actes 19 : 1-5).\r\n\r\nCes exemples montrent que les apôtres ne semblent pas avoir instauré une longue période obligatoire entre la foi et le baptême. Cependant, ils enseignaient la Parole afin que ceux qui la recevaient comprennent en qui ils plaçaient leur foi.\r\n\r\nIl faut également reconnaître que l’être humain ne peut connaître parfaitement le cœur de celui qui demande le baptême. À l’exemple de Shim‘own[[FN:7]], le magicien à Samarie, est instructif : il crut et fut baptisé, mais son état intérieur fut ensuite révélé lorsqu’il voulut obtenir par de l’argent le pouvoir lié au don du Saint-Esprit (Actes 8 : 9-24). Petros lui demanda alors de se repentir.\r\n\r\nCe n’est pas à l’homme de sonder les autres mais c’est le travail du Saint-Esprit.\r\n\r\n## Les baptêmes par aspersion et par effusion sont-ils bibliques ?\r\n\r\nLe baptême par aspersion consiste à projeter ou asperger de l’eau sur une personne. Le baptême par effusion consiste à verser de l’eau sur sa tête. Ce sont des doctrines anti-bibliques pratiquées dans les églises catholiques et d’autres courant religieux se réclamant de Yehowshuw‘a ha-Mashiyah comme le protestantisme traditionnel.\r\n\r\nToutes ces pratiques sont tirées des traditions et non de la Parole d’Èlohiym. Voici ce qui est tiré de l’une de ses religions :\r\n\r\n« Quant au baptême, baptisez au nom du Père, du Fils et du Saint-Esprit dans l’eau vive. Mais, si tu n’as pas d’eau vive, baptise dans une autre eau ; si tu ne peux pas (baptiser) dans l’eau froide, que ce soit dans l’eau chaude. Si tu n’as ni l’une ni l’autre (en quantité suffisante), verse trois fois de l’eau sur la tête au nom du Père, du Fils et du Saint Esprit » Didachè 7 : 1-2[[FN:8]].\r\n\r\nCe texte, comme dit l’Écriture, est d’inspiration démoniaque car ce livre n’appartient pas au canon biblique et est en total déphasage avec l’enseignement apostolique :\r\n\r\n« Mais l’Esprit dit expressément que dans les derniers temps, certains s’éloigneront de la foi, s’attachant à des esprits trompeurs et des doctrines de démons » (1 Timothée 4 : 1) ;\r\n\r\n« Car je rends témoignage à quiconque entend les paroles de la prophétie de ce livre : si quelqu’un y ajoute quelque chose, Elohîm le frappera des fléaux décrits dans ce livre. Et si quelqu’un retranche quelque chose des paroles du livre de cette prophétie, Elohîm retranchera sa part du livre de vie, de la cité sainte et des choses qui sont écrites dans ce livre » (Apocalypse 22 : 18 ; Voir aussi Actes 17 : 11 ; 1 Corinthiens 4 : 6 ; Hébreux 1 : 1-3).\r\n\r\nLe seul et unique baptême que la Bible reconnaît et recommande est le baptême où l’on est totalement immergé de la tête à la plante des pieds.\r\n\r\nDeux exemples dans la Bible nous montrent comment les nouveaux croyants étaient baptisés. A l’exemple de :\r\n\r\n« Et ayant été baptisé, Yéhoshoua remonta directement de l\u0027eau. Et voici, les cieux lui furent ouverts, et il vit l\u0027Esprit d\u0027Elohîm descendant comme une colombe et venant sur lui. » (Matthieu 3 : 16) ;\r\n\r\n« Et il ordonna d\u0027arrêter le char. Ils descendirent tous les deux dans l’eau, Philippos et l\u0027eunuque, et il le baptisa. Mais, quand ils furent remontés de l’eau, l’Esprit du Seigneur enleva Philippos, et l’eunuque ne le vit plus, car il poursuivait sa route en se réjouissant. » (Actes 8 : 38-39) ;\r\n\r\n## Que le symbolise le baptême dans l’eau ?\r\n\r\nL’apôtre Paulus déclarait aux romains :\r\n\r\n« Nous avons donc été ensevelis avec lui par le moyen du baptême pour la mort, afin que, comme Mashiah a été réveillé hors des morts par le moyen de la gloire du Père, de même nous aussi nous marchions en nouveauté de vie. Car si nous sommes nés ensemble avec lui en devenant semblables à sa mort, et nous le serons aussi à sa résurrection. » Romains 6 : 4-5.\r\n\r\nCe passage illustre bien la symbolique qui est cachée derrière le baptême en Yehowshou‘a ha-Mashiya’h. En effet, lorsqu’une personne entre dans les eaux, elle meurt à son ancienne vie. Et lorsqu’elle en ressort, cela signifie qu’elle ressuscite pour une nouvelle vie, celle en Mashiya’h.\r\n\r\n## Qu’est-ce que le baptême pour les morts ?\r\n\r\n« Autrement, que feront ceux qui sont baptisés pour les morts ? Si les morts ne ressuscitent absolument pas, pourquoi aussi sont-ils baptisés pour les morts ? » (1 Corinthiens 15 : 29).\r\n\r\nCe passage, tiré de la première Épître aux Corinthiens et rédigé par l’apôtre Paulus, nous présente une pratique religieuse de la ville de Corinthe. En effet, certains Corinthiens se faisaient baptiser pour les morts en vue d’offrir une espérance de vie éternelle aux personnes décédées.\r\n\r\nL’apôtre Paulus se sert ainsi de cette habitude culturelle afin d\u0027interpeller les chrétiens de Corinthe sur la réalité de la résurrection, alors qu’ils étaient troublés par des détracteurs de l’Évangile. Il ne leur demandait pas d\u0027adopter cette pratique, mais voulait plutôt leur démontrer une chose : si ces hommes qui ne connaissaient pas le vrai \u0027Èlohiym avaient une telle espérance dans l\u0027au-delà, à combien plus forte raison eux, qui ont cru en Yehowshou‘a ha-Mashiya’h — ressuscité des morts et vivant pour l’éternité — devaient-ils y croire ! Amen !\r\n\r\n## Paulus ordonne-t-il le baptême pour les morts ?\r\n\r\nBien évidemment que non. En effet, nous n’avons aucun ordre apostolique pour pouvoir le faire. L’apôtre Paulus n’en parle pas comme une pratique chrétienne mais une pratique païenne.\r\n\r\n## Devons-nous aussi observer le baptême pour les morts ?\r\n\r\nLa réponse est non. L’Écriture ne contient aucun commandement ni aucun fondement doctrinal invitant les croyants à observer une telle pratique. Même si l’apôtre Paul y fait une allusion culturelle isolée dans 1 Corinthiens 15 : 29, l’Église primitive n’a jamais établi cette ordonnance. Il s’agit d’une déviation théologique sans appui biblique.\r\n\r\nPourtant, un mouvement comme l’Église de Jésus-Christ des Saints des Derniers Jours (communément appelée l’Église mormone) pratique le baptême par procuration en faveur des défunts. Un membre vivant est baptisé au nom d’un défunt. Selon leur enseignement, ce baptême ne contraint toutefois pas la personne décédée : celle-ci conserverait, dans l’au-delà, la possibilité d’accepter ou de rejeter l’ordonnance accomplie en son nom[[FN:9]].\r\n\r\nCette pratique introduit l’idée d’une possibilité de salut après la mort. Or, l\u0027Enseignement biblique est formel sur l\u0027irréversibilité de la condition spirituelle après le trépas :\r\n\r\n« Mais afin que vous sachiez que le Fils de l’homme a l’autorité de remettre les péchés sur la Terre – il dit au paralytique : je te dis : Lève-toi, prend ton petit lit, et va dans ta maison » (Marc 2 : 10) ;\r\n\r\n« Et comme il est réservé aux humains de mourir une seule fois, après cela vient le jugement » (Hébreux 9 : 27).\r\n\r\nLe salut s’obtient exclusivement par la foi exprimée durant notre vie sur Terre. Après la mort, le destin spirituel de chacun est définitivement scellé.\r\n\r\n## Le baptême dans l’eau sauve-t-il ?\r\n\r\nD’une part, nous pouvons affirmer que le baptême d’eau ne sauve pas en lui-même. Il ne s’agit pas d’un rite magique, mais d’un acte symbolique figurant notre mort à l’ancienne vie et notre résurrection en Yehowshou‘a ha-Mashiya’h. Ce qui régénère véritablement l’âme, c’est le baptême dans le Saint-Esprit, qui nous greffe au corps du Mashiya’h et fait de nous des membres de la famille d’Èlohiym.\r\n\r\nLa Bible nous en donne un exemple éclairant avec Simon le magicien en Samarie : bien qu’ayant cru superficiellement et ayant été baptisé d’eau par Philippe, son cœur n’était pas droit devant ’Èlohiym (Actes 8). Inversement, lors de la crucifixion, l’un des malfaiteurs a été sauvé uniquement en plaçant sa foi et sa repentance en Yehowshou‘a ha-Mashiya’h :\r\n\r\n« Et l’un des malfaiteurs qui étaient crucifiés blasphémait contre lui en disant : Si tu es le Mashiah, sauve-toi toi-même et sauve-nous ! Mais l’autre répondant, le réprimandait d’une manière tranchante en disant : Ne crains-tu pas Elohîm, toi, puisque tu es sous le même jugement ? Et pour nous, en effet c’est juste, car nous recevons ce que méritent les choses que nous avons commises, mais celui-ci n’a fait aucun mal. Et il disait à Yéhoshoua : Seigneur, souviens-toi de moi quand tu viendras dans ton royaume ! Et Yéhoshoua lui dit : Amen, je te le dis, aujourd’hui tu seras avec moi dans le paradis » (Luc 23 : 36-43).\r\n\r\nCe brigand n’a pas pu recevoir le baptême d’eau, mais sa foi sincère et sa repentance ont suffi à son salut.\r\n\r\nD’autre part, le baptême d’eau demeure un acte salutaire et indispensable en tant que commandement direct du Seigneur. Yehowshou‘a ha-Mashiya’h a ordonné à ses apôtres de faire de toutes les nations des disciples et de les baptiser (Matthieu 28 : 19-20), déclarant également :\r\n\r\n« Celui qui croira et qui se sera baptisé sera sauvé, mais celui qui ne croira pas sera condamné » (Marc 16 : 16).\r\n\r\nAinsi, bien que l\u0027eau ne sauve pas par elle-même, le refus délibéré et obstiné de se faire baptiser — alors que toutes les conditions sont réunies — traduit un cœur désobéissant à la Parole d’Èlohiym. Une foi qui rejette ouvertement les commandements du Seigneur ne peut être une foi salvatrice.\r\n\r\n## En quel Nom devons-nous baptiser ?\r\n\r\nUne apparente contradiction s’est installée chez de nombreux lecteurs de la Bible concernant le baptême. D\u0027un côté, le Seigneur Jésus donne cette instruction avant d\u0027monter au ciel :\r\n\r\n« Allez donc et faite toutes les nations des disciples, les baptisant dans le Nom du Père, du Fils et du Saint-Esprit, leur enseignant à garder tout ce que je vous ai ordonné. Et voici, je suis avec vous tous les jours jusqu’à l’achèvement de l’âge. Amen ! » (Matthieu 28 : 19-20).\r\n\r\nD\u0027un autre côté, lorsque nous observons la pratique des apôtres dans le livre des Actes, aucun d\u0027entre eux n\u0027a répété machinalement la formule « du Père, du Fils et du Saint-Esprit ». Ils baptisaient tous au Nom du Seigneur Yehowshou‘a :\r\n\r\n« Et Petros leur dit : Repentez-vous et que chacun soit baptisé au Nom de Yéhoshoua Mashiah pour le pardon de vos péchés, et vous recevrez le don du Saint-Esprit » (Actes 2 : 38) ; voir aussi 10 : 47-48 ; 19 : 5 ; Romains 6 : 3).\r\n\r\nCette divergence s’explique lorsque l’on comprend l’identité profonde de Yehowshou‘a ha-Mashiya’h. Dans Matthieu 28 : 19, le mot « Nom » est au singulier. Les apôtres avaient saisi que le Père, le Fils et le Saint-Esprit ne sont pas trois noms distincts, mais différente de l’unique ’Èlohiym d’Abraham, de Yitshaq et de Ya‘aqov, incarné en Yéhoshoua (Jésus). C’est pourquoi ils ont invoqué le Nom suprême dans lequel réside la plénitude de la Divinité :\r\n\r\n« Et sans contredit, le mystère de la piété est grand : Elohîm a été manifesté en chair, justifié par l’Esprit, vu des anges, prêché aux nations, cru dans le monde et élevé dans la gloire » (1 Timothée 3 : 13) ;\r\n\r\n« Shim‘ôn Petros, esclave et apôtre de Yéhoshoua Mashiah, à vous qui avez reçu en partage une foi du même prix que la nôtre, par la justice de notre Elohîm et Sauveur Yéhoshoua Mashiah » (2 Pierre 1 : 1 ; Voir aussi 2 Corinthiens 5 : 18-19 ; Colossiens 2 : 9 ; 1 Jean 5 : 20-21).\r\n\r\nAinsi, le seul Nom par lequel le baptême prend tout son sens d’alliance et de salut, c’est le Nom de Yehowshou‘a ha-Mashiya’h :\r\n\r\n« Et il n’y a de salut en aucun autre, car il n’y a sous le ciel aucun autre Nom qui a été donné aux humains par lequel nous devons être sauvés. » (Actes 4 : 12).\r\n\r\n## Un chrétien pas encore baptisé, peut-il manger le repas du Seigneur ?\r\n\r\nUn chrétien qui a sincèrement accepté le Christ (le Véritable Agneau pascal, 1 Corinthiens 5 : 7-8) est régénéré par l’Esprit et appartient à la famille d’Èlohiym. En ce sens, le repas du Seigneur s’adresse prioritairement à ceux qui partagent cette foi. Néanmoins, l’Écriture lie étroitement la conversion au baptême comme premier acte d’obéissance publique. Si une personne est convertie mais n’est pas encore baptisée pour des raisons de calendrier ou de parcours, elle peut prendre part au Repas du Seigneur. En revanche, un refus délibéré et persistant du baptême témoigne d’une résistance à l’enseignement du Seigneur, ce qui remet en question sa participation à la table de la Communion.\r\n\r\n## Est-il biblique de se refaire baptiser ?\r\n\r\nLa Bible enseigne qu’il y a « un seul Seigneur, une seule foi, un seul baptême » (Éphésiens 4 : 5). En principe, un baptême chrétien authentique et valide n\u0027a donc pas à être répété.\r\n\r\nCependant, un nouveau baptême peut s’avérer nécessaire si l’acte initial n’était pas fondé sur la véritable doctrine apostolique. Si une personne a été baptisée dans un cadre dont l’enseignement s’écartait fondamentalement de la foi transmise par Yehowshou‘a ha-Mashiya’h et les apôtres, son premier baptême ne peut être considéré comme le baptême chrétien.\r\n\r\nL’apôtre Paulus illustre ce principe lorsqu’il rencontre des disciples à Éphèse :\r\n\r\n« Or il arriva, pendant qu’Apollos était à Corinthe, que Paulus, après avoir traversé les contrées supérieures, arriva à Ephèse. Et ayant trouvé quelques disciples, il leur dit : Avez-vous reçu le Saint-Esprit après avoir cru ? Et ils lui dirent : Mais nous n’avons même pas entendu dire qu’il y ait un Saint-Esprit. Et il leur dit : Dans quoi avez-vous été baptisés ? Et ils dirent : Dans le baptême de Yohanan. Mais Paulus dit : En effet, Yohanan a baptisé du baptême de repentance, en disant au peuple de croire en celui qui venait après lui, c’est-à-dire, en Yéhoshoua Mashiah. Mais après avoir entendu cela, ils furent baptisés dans le Nom du Seigneur Yéhoshoua » (Actes 19 : 1-5).\r\n\r\n## Qu’est-ce que le baptême dans le feu ?\r\n\r\nC’est l’ensemble des épreuves, des souffrances et des persécutions que le Seigneur permet dans la vie de ses disciples pour éprouver, purifier et affermir leur foi (1 Pierre 1 : 6-7 ; 4 : 12-14).\r\n\r\nYehowshou‘a ha-Mashiya’h fait référence à cette réalité sous la figure de la « coupe » et du « baptême » de la souffrance qu\u0027il devait lui-même accomplir :\r\n\r\n« Et Yéhoshoua répondit et dit : Vous ne savez pas ce que vous demandez. Pouvez-vous boire la coupe que je suis sur le point de boire ou être baptisés du baptême dont je dois être baptisé ? Ils lui disent : Nous le pouvons. Et il leur dit : En effet, vous boirez ma coupe et vous serez baptisés du baptême dont je serai baptisé. Mais pour ce qui est d’être assis à ma droite ou ma gauche, il ne m’appartient de le donner qu’à ceux pour qui cela a été préparé par mon Père. » (Matthieu 20 : 22-23 ; Voir aussi Actes 4 : 1-4 ; 8 : 1-3 ; 1 Thessaloniciens 3 : 1-4 ; 2 Corinthiens 1 : 1-7 ; 2 Timothée 3 : 11-12 ; 1 Pierre 1 : 3-8 ; 4 : 12-14).\r\n\r\nCependant, si une personne souffre en raison de ses propres fautes ou d\u0027un manque de sagesse, elle ne doit pas attribuer cela à une épreuve venant du Seigneur, mais aux conséquences naturelles de ses actes (1 Pierre 3 : 17 ; 4 : 15).\r\n\r\nQue toute la Gloire et l’honneur soient rendus à notre ’Èlohiym Yehowshuw‘a ha-Mashiyah pour cet enseignement, ainsi que la force et l’énergie qu’il nous a accordées afin de vous le présenter.\r\n\r\nNotre prière pour vous est que le Seigneur vous fortifie dans ses voies en ces temps si difficiles. Ainsi, malgré les épreuves par lesquelles vous pouvez passer, qu’il vous accorde toujours la force nécessaire pour continuer d’avancer avec lui. En effet, « Aucune épreuve ne vous est survenue qui n’ait été humaine. Mais Elohîm qui est fidèle ne permettra pas que vous soyez mis à l’épreuve au-delà de vos forces, mais avec l’épreuve, il préparera aussi le moyen d’en sortir, pour que vous puissiez la supporter » (1 Corinthiens 13 : 10).\r\n\r\nQu’il vous bénisse abondamment et vous remplisse puissamment de son Saint-Esprit, au Nom puissant de Yehowshuw‘a ha-Mashiyah. Amen !\r\n\r\n");
